//! New, rename, delete, copy, paste, save.
//!
//! Everything that changes the filesystem on the user's say-so. What they have
//! in common is that each one is a small transaction with three parts: work
//! out the target, do it, and say what happened — and that the saying is not
//! optional, because a file manager that silently does nothing is
//! indistinguishable from one that is broken.
//!
//! # Nothing destructive happens on one key
//!
//! Delete is armed and then confirmed; quitting with unsaved work asks and
//! names the files. Paste never overwrites — [`free_name`] finds an unused
//! name beside the existing one instead, so the worst a mistaken paste costs
//! you is a copy to delete.
//!
//! # Buffers follow their files
//!
//! A rename moves the buffer's entry to the new key, so unsaved edits follow
//! the file rather than being stranded under a path that no longer exists. A
//! delete drops the entry and everything under it.

use std::fs;
use std::path::{Path, PathBuf};

use anyhow::{Context, Result, anyhow};

use crate::text::editor::Editor;

use super::App;
use super::mode::{Confirm, ConfirmKind, Focus, Mode};
use super::parts::{display_name, safe_join};
use super::preview::Preview;

/// Copy a directory and everything under it.
///
/// Recurses on directories and copies everything else with `fs::copy`, which
/// carries permissions across on every platform. A symlink counts as
/// "everything else": its target is copied as a plain file rather than
/// followed as a directory, so a link pointing back up its own tree cannot
/// send this into a loop.
fn copy_tree(src: &Path, dst: &Path) -> std::io::Result<()> {
    fs::create_dir_all(dst)?;
    for entry in fs::read_dir(src)? {
        let entry = entry?;
        let target = dst.join(entry.file_name());
        // `DirEntry::file_type` does not follow links, which is what keeps the
        // symlink case out of the recursive branch.
        if entry.file_type()?.is_dir() {
            copy_tree(&entry.path(), &target)?;
        } else {
            fs::copy(entry.path(), &target)?;
        }
    }
    Ok(())
}

/// A free path in `dir` for something named after `src`: `notes.md`, then
/// `notes copy.md`, then `notes copy 2.md`.
///
/// Only paste uses this. The words are spelled out rather than punctuated —
/// `notes copy.md`, not `notes(1).md` — because everything else the command
/// bar shows reads as English too.
fn free_name(dir: &Path, src: &Path) -> Result<PathBuf> {
    let name = src
        .file_name()
        .ok_or_else(|| anyhow!("cannot copy {}", display_name(src)))?;
    let first = dir.join(name);
    if !first.exists() {
        return Ok(first);
    }
    let name = Path::new(name);
    let stem = name
        .file_stem()
        .unwrap_or(name.as_os_str())
        .to_string_lossy();
    let ext = name.extension().map(|e| e.to_string_lossy());
    for n in 1..100 {
        let base = if n == 1 {
            format!("{stem} copy")
        } else {
            format!("{stem} copy {n}")
        };
        let candidate = match &ext {
            Some(e) => dir.join(format!("{base}.{e}")),
            None => dir.join(base),
        };
        if !candidate.exists() {
            return Ok(candidate);
        }
    }
    Err(anyhow!("too many copies of {}", display_name(src)))
}

impl App {
    /// `Ctrl+C`: remember what the cursor is on. Nothing is read or written
    /// until the paste.
    pub(super) fn copy_selection(&mut self) {
        let Some(row) = self.selected_row().cloned() else {
            return;
        };
        if row.path == self.tree.root_path() {
            self.status = "cannot copy the project root".into();
            return;
        }
        self.status = format!("copied {} — ^V to paste", row.name);
        self.clipboard = Some(row.path);
    }

    /// `Ctrl+V`: drop the clipboard into the folder the cursor is in.
    ///
    /// Where `*copy` refuses to write over something — you named that
    /// destination, so a collision means you were wrong about it — a paste
    /// picks the next free name instead. The destination here is implied
    /// rather than stated, and pasting into the folder you copied from is the
    /// ordinary way to duplicate a file; erroring there would make the gesture
    /// useless.
    pub(super) fn paste_clipboard(&mut self) {
        let Some(src) = self.clipboard.clone() else {
            self.status = "nothing copied — ^C first".into();
            return;
        };
        let base = self.creation_base();
        let dst = match free_name(&base, &src) {
            Ok(p) => p,
            Err(e) => {
                self.status = format!("{e:#}");
                return;
            }
        };
        match self.copy_entry(&src, &dst) {
            Ok(msg) => self.status = msg,
            Err(e) => self.status = format!("{e:#}"),
        }
    }

    /// Copy a file, or a whole folder, to a new path inside the project.
    ///
    /// Naming an existing folder as the destination copies *into* it, which is
    /// what `copy README.md to notes` reads like. Anything else is the new name
    /// itself, and an existing one is never written over.
    pub(super) fn copy_entry(&mut self, src: &Path, dst: &Path) -> Result<String> {
        let meta = fs::symlink_metadata(src)
            .with_context(|| format!("cannot copy {}", display_name(src)))?;
        // `copy a to notes` means "put a in notes", not "rename a to notes".
        let dst = if dst.is_dir() {
            match src.file_name() {
                Some(name) => dst.join(name),
                None => return Err(anyhow!("cannot copy {}", display_name(src))),
            }
        } else {
            dst.to_path_buf()
        };
        if dst == src {
            return Err(anyhow!("{} is already there", display_name(src)));
        }
        if dst.exists() {
            return Err(anyhow!("{} already exists", display_name(&dst)));
        }
        // Copying a folder into itself would walk into what it is writing.
        if meta.is_dir() && dst.starts_with(src) {
            return Err(anyhow!("cannot copy {} into itself", display_name(src)));
        }
        if let Some(parent) = dst.parent() {
            fs::create_dir_all(parent)
                .with_context(|| format!("cannot create {}", parent.display()))?;
        }

        if meta.is_dir() {
            copy_tree(src, &dst)
        } else {
            fs::copy(src, &dst).map(|_| ())
        }
        .with_context(|| {
            format!(
                "cannot copy {} to {}",
                display_name(src),
                display_name(&dst)
            )
        })?;

        self.tree.refresh_all();
        self.reveal(&dst);
        Ok(format!(
            "copied {} to {}",
            display_name(src),
            display_name(&dst)
        ))
    }

    /// Write the current buffer. Reports "nothing to save" for a non-text
    /// preview and "no changes" for a clean one, rather than silently doing
    /// nothing in either case.
    pub fn save_active(&mut self) {
        let Some(ed) = self.active_buffer_mut() else {
            self.status = "nothing to save".into();
            return;
        };
        if !ed.dirty {
            self.status = "no changes".into();
            return;
        }
        let path = ed.path.clone();
        let name = display_name(&path);
        match ed.save() {
            Ok(()) => {
                self.status = format!("saved {name}");
                self.plugin_event("save", &path);
            }
            Err(e) => self.status = format!("save failed: {e}"),
        }
        // The file just changed length under a cursor that did not move, and
        // the readout at the end of the status line is showing what it was.
        self.note_size();
    }

    /// `Ctrl+S` from the tree: save what the cursor is on.
    ///
    /// On a file that is the file. On a folder it is everything unsaved
    /// underneath it, however deep — so the root row saves the whole project
    /// and a subfolder saves just its own. That makes the one key mean "save
    /// this", whatever "this" happens to be, which is the same thing the tree
    /// cursor means everywhere else in the program.
    pub(super) fn save_from_tree(&mut self) {
        let Some(row) = self.selected_row().cloned() else {
            return self.save_active();
        };
        if !row.is_dir {
            return self.save_active();
        }
        let under: Vec<PathBuf> = self
            .buffers
            .values()
            .filter(|e| e.dirty && e.path.starts_with(&row.path))
            .map(|e| e.path.clone())
            .collect();
        if under.is_empty() {
            self.status = format!("nothing to save in {}", row.name);
            return;
        }
        // Sorted so the report is stable, and so the first failure named is
        // the same one on every run.
        let mut under = under;
        under.sort();
        let (saved, failed) = self.save_each(&under);
        self.status = match failed.first() {
            Some(first) => format!("saved {saved}, {} failed — {first}", failed.len()),
            None if saved == 1 => format!("saved {}", display_name(&under[0])),
            None => format!("saved {saved} files in {}", row.name),
        };
    }

    /// Write each of `paths` that is open, returning how many were written
    /// and one message per failure.
    ///
    /// Every save in tiny that touches more than one file goes through here:
    /// saving a folder from the tree, and answering yes to the question on the
    /// way out. Both need the same thing — keep going after a failure, and be
    /// able to say afterwards which ones did not make it. A loop that stopped
    /// at the first error would leave the rest unsaved without saying so.
    ///
    /// Paths with no buffer open are skipped rather than reported: nothing was
    /// asked of them.
    pub(super) fn save_each(&mut self, paths: &[PathBuf]) -> (usize, Vec<String>) {
        let (mut saved, mut failed) = (0usize, Vec::new());
        for path in paths {
            match self.buffers.get_mut(path).map(Editor::save) {
                Some(Ok(())) => {
                    saved += 1;
                    self.plugin_event("save", path);
                }
                Some(Err(e)) => failed.push(format!("{}: {e}", display_name(path))),
                None => {}
            }
        }
        (saved, failed)
    }

    /// Where a new file or folder should go: the selected directory, or the
    /// parent of the selected file. Matches what most file managers do, and
    /// means you rarely have to type a path.
    pub(super) fn creation_base(&self) -> PathBuf {
        match self.selected_row() {
            Some(r) if r.is_dir => r.path.clone(),
            Some(r) => r
                .path
                .parent()
                .map(Path::to_path_buf)
                .unwrap_or_else(|| self.tree.root_path().to_path_buf()),
            None => self.tree.root_path().to_path_buf(),
        }
    }

    /// Create a file or directory. A name containing separators creates the
    /// intermediate directories too, so `notes/2026/today.md` works in one go.
    pub(super) fn create_entry(&mut self, base: &Path, name: &str, is_dir: bool) -> Result<String> {
        let target = safe_join(base, name, self.tree.root_path())?;
        if target.exists() {
            return Err(anyhow!("{} already exists", display_name(&target)));
        }
        if is_dir {
            fs::create_dir_all(&target)
                .with_context(|| format!("cannot create {}", target.display()))?;
        } else {
            if let Some(parent) = target.parent() {
                fs::create_dir_all(parent)
                    .with_context(|| format!("cannot create {}", parent.display()))?;
            }
            fs::write(&target, "")
                .with_context(|| format!("cannot create {}", target.display()))?;
        }
        self.tree.refresh_all();
        if is_dir {
            self.tree.expand(&target);
        }
        self.reveal(&target);
        Ok(format!("created {}", display_name(&target)))
    }

    /// Move `from` to `target`, carrying any open buffer with it so unsaved
    /// edits follow the file to its new name. Refuses to overwrite.
    ///
    /// One path in and one path out, rather than "the selection, renamed
    /// within its folder", because `*rename a to b` can move a file between
    /// folders and the old naming prompt could not. Both are still a rename to
    /// the filesystem, which is the only reason this is not called move.
    pub(super) fn rename_path(&mut self, from: &Path, target: &Path) -> Result<String> {
        if from == self.tree.root_path() {
            return Err(anyhow!("cannot rename the project root"));
        }
        if !from.exists() {
            return Err(anyhow!("{} is not here", display_name(from)));
        }
        if target == from {
            return Ok("unchanged".into());
        }
        if target.exists() {
            return Err(anyhow!("{} already exists", display_name(target)));
        }
        if let Some(parent) = target.parent() {
            fs::create_dir_all(parent)?;
        }
        fs::rename(from, target)
            .with_context(|| format!("cannot rename {}", display_name(from)))?;

        // Carry any open buffer, and its unsaved edits, to the new path.
        if let Some(mut ed) = self.buffers.remove(from) {
            ed.path = target.to_path_buf();
            self.buffers.insert(target.to_path_buf(), ed);
            self.highlight_cache.clear();
        }
        self.tree.refresh_all();
        self.reveal(target);
        Ok(format!(
            "renamed {} to {}",
            display_name(from),
            display_name(target)
        ))
    }

    /// Put up the yes/no question for removing `path`.
    ///
    /// The single gate on every delete, and there is now only one way in:
    /// `*delete`, with a path or with none for whatever the cursor is on.
    /// Deleting used to have a key as well, which is exactly the overlap that
    /// went — it is a deliberate act, and a deliberate act can afford to be
    /// typed. Nothing touches the disk until [`App::do_delete`].
    ///
    /// The message counts a directory's entries first, because `remove_dir_all`
    /// takes everything underneath and the number should be on screen before
    /// anyone presses `y`.
    pub(super) fn arm_delete(&mut self, path: &Path) -> Result<()> {
        if path == self.tree.root_path() {
            return Err(anyhow!("cannot delete the project root"));
        }
        // `symlink_metadata` rather than `exists`, which follows links and so
        // reports a broken symlink as missing — that is a thing you very much
        // want to be able to delete.
        let meta = fs::symlink_metadata(path)
            .with_context(|| format!("cannot delete {}", display_name(path)))?;
        let name = display_name(path);
        // Say how much is at stake before asking — deleting a folder takes
        // everything under it.
        let message = if meta.is_dir() {
            let n = fs::read_dir(path).map(|d| d.count()).unwrap_or(0);
            format!(
                "Delete folder {} and its {} entr{}?  (y/n)",
                name,
                n,
                if n == 1 { "y" } else { "ies" }
            )
        } else {
            format!("Delete {name}?  (y/n)")
        };
        self.mode = Mode::Confirm(Confirm {
            kind: ConfirmKind::Delete(path.to_path_buf()),
            message,
        });
        Ok(())
    }

    /// Carry out a confirmed delete, then put the cursor somewhere sensible.
    ///
    /// Buffers under the deleted path are dropped — including unsaved ones,
    /// since there is no longer a file to save them to. The cursor moves to the
    /// parent directory where it can, rather than staying on an index that now
    /// points at a different file.
    pub(super) fn do_delete(&mut self, path: &Path) {
        // `symlink_metadata` again, so a link is unlinked rather than followed
        // into: deleting a shortcut must never delete what it points at.
        let is_dir = fs::symlink_metadata(path)
            .map(|m| m.is_dir())
            .unwrap_or(false);
        let result = if is_dir {
            fs::remove_dir_all(path)
        } else {
            fs::remove_file(path)
        };
        match result {
            Ok(()) => {
                self.buffers.retain(|p, _| !p.starts_with(path));
                let parent = path.parent().map(Path::to_path_buf);
                self.tree.refresh_all();
                self.rows = self.tree.flatten();
                if let Some(i) = parent.and_then(|p| self.rows.iter().position(|r| r.path == p)) {
                    self.selected = i;
                } else {
                    self.selected = self.selected.min(self.rows.len().saturating_sub(1));
                }
                self.sync_preview();
                // `*delete` can be run from the editor. If the pane holding the
                // keyboard just lost its file, the tree is the only place left
                // with something to point at.
                if self.focus == Focus::Editor && !matches!(self.preview, Preview::Buffer { .. }) {
                    self.focus_tree();
                }
                self.status = format!("deleted {}", display_name(path));
            }
            Err(e) => self.status = format!("delete failed: {e}"),
        }
    }
}

files.src/app/input.rs:
//! Every keypress, and where it goes.
//!
//! [`App::handle_key`] is the whole of tiny's input handling, and it
//! dispatches on [`Mode`] first and [`Focus`] second — see the folder's docs
//! for why those two answer almost every "why did that key do that".
//!
//! # The mode take-and-replace pattern
//!
//! `handle_key` does `std::mem::replace(&mut self.mode, Mode::Normal)` and
//! hands the owned mode to a handler. That is not only a borrow-checker
//! workaround: it makes **closing the default and staying open explicit**. A
//! handler that does nothing leaves `Normal` behind, so every handler that
//! wants its overlay to persist has to put it back. Forget it and the overlay
//! closes, which is the right direction for that mistake to fail in.
//!
//! # The wheel
//!
//! One notch, one line, and nothing else the mouse reports is listened to.
//! [`App::on_scroll`] takes the column so it can tell which pane the pointer
//! was over, which is the only thing tiny ever asks the mouse's position.

use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};

use crate::config::keys::{Action, Context as KeyContext, from_terminal};
use crate::map::view::Intent;
use crate::text::editor::Editor;

use super::App;
use super::mode::{Focus, Mode, Window};
use super::parts::list_move;
use super::preview::Preview;
use super::source::GitFocus;

/// Apply one key to a buffer, and say what to complain about if anything.
///
/// The one text-editing keyboard in tiny, in one place. The editor pane uses
/// it, and so does the commit message box in the source window — two panes that
/// type, which must not disagree about what Backspace does.
///
/// `action` is what the keymap made of the key, already resolved by the caller
/// so the borrow of the buffer can come after it. Anything the keymap did not
/// name falls through to the fixed half: the arrows, Enter, Backspace and the
/// characters themselves, which are not bindable because a keyboard that cannot
/// type is not a keyboard.
pub(super) fn edit_with_key(
    ed: &mut Editor,
    action: Option<Action>,
    key: KeyEvent,
    page: usize,
    tab_width: usize,
) -> Option<&'static str> {
    match action {
        Some(Action::EditorUndo) => return (!ed.undo()).then_some("nothing to undo"),
        Some(Action::EditorRedo) => return (!ed.redo()).then_some("nothing to redo"),
        Some(Action::EditorDeleteLine) => {
            ed.delete_line();
            return None;
        }
        Some(Action::EditorWordLeft) => {
            ed.move_word_left();
            return None;
        }
        Some(Action::EditorWordRight) => {
            ed.move_word_right();
            return None;
        }
        Some(Action::PageUp) => {
            ed.page_up(page);
            return None;
        }
        Some(Action::PageDown) => {
            ed.page_down(page);
            return None;
        }
        Some(Action::EditorLineStart) => {
            ed.move_home();
            return None;
        }
        Some(Action::EditorLineEnd) => {
            ed.move_end();
            return None;
        }
        Some(Action::EditorDocStart) => {
            ed.move_doc_start();
            return None;
        }
        Some(Action::EditorDocEnd) => {
            ed.move_doc_end();
            return None;
        }
        _ => {}
    }
    match key.code {
        KeyCode::Left => ed.move_left(),
        KeyCode::Right => ed.move_right(),
        KeyCode::Up => ed.move_up(),
        KeyCode::Down => ed.move_down(),
        KeyCode::PageUp => ed.page_up(page),
        KeyCode::PageDown => ed.page_down(page),
        KeyCode::Enter => ed.insert_newline(),
        KeyCode::Backspace => ed.backspace(),
        KeyCode::Delete => ed.delete_forward(),
        KeyCode::Tab => ed.insert_tab(tab_width),
        KeyCode::Char(c) if !key.modifiers.contains(KeyModifiers::CONTROL) => ed.insert_char(c),
        _ => {}
    }
    None
}

impl App {
    // ---- key dispatch -----------------------------------------------------

    /// One key, and everything it leads to, done before this returns — how
    /// the tests type.
    ///
    /// The event loop does not use this: with several keys already waiting it
    /// hands each to [`App::handle_key`] and calls [`App::settle`] once, so a
    /// burst of typing into the bar is searched for once rather than once a
    /// letter.
    #[cfg(test)]
    pub fn on_key(&mut self, key: KeyEvent) {
        self.handle_key(key);
        self.settle();
    }

    /// The single entry point for input. Dispatches in strict priority order:
    /// map, then mode, then focus.
    ///
    /// See the module docs for the take-and-replace pattern: the mode is moved
    /// out and `Normal` left in its place, so a handler that does nothing
    /// closes its overlay, and one that wants to stay open has to say so.
    ///
    /// Work that only matters to what is drawn next — a search of the
    /// project — is left for [`App::settle`].
    pub fn handle_key(&mut self, key: KeyEvent) {
        // One spelling per key, before anything reads it: macOS Terminal's
        // `⌥←` arrives as `Alt+B`, and becomes the arrow it was.
        let key = from_terminal(key);
        // The window switcher answers before anything else, from every window
        // and through every overlay. A key that changes which window you are
        // looking at cannot be one that a pane might swallow first, or it
        // would work from some places and not others.
        if let Some(window) = self.window_key(&key) {
            return self.toggle_window(window);
        }
        // An overlay owns the keyboard wherever it was opened from — the bar
        // is drawn over every window, so it has to be typed into from every
        // window. Taken out and left as `Normal`, so a handler that does
        // nothing closes it; see the module docs.
        if !matches!(self.mode, Mode::Normal) {
            return match std::mem::replace(&mut self.mode, Mode::Normal) {
                Mode::Help(scroll) => self.on_help_key(scroll, key),
                Mode::Confirm(c) => self.on_confirm_key(c, key),
                Mode::Bar(b) => self.on_bar_key(b, key),
                Mode::Settings(s) => self.on_settings_key(s, key),
                Mode::Keybinds(kb) => self.on_keybinds_key(kb, key),
                Mode::Normal => {}
            };
        }
        // With nothing over it, the window that is not the main one takes the
        // whole screen and every key with it.
        match self.window {
            Window::Map => self.on_map_key(key),
            Window::Source => self.on_source_key(key),
            Window::Main => match self.focus {
                Focus::Tree => self.on_tree_key(key),
                Focus::Editor => self.on_editor_key(key),
            },
        }
    }

    /// Keys for the source-control window.
    ///
    /// The same shape as the map's: the window owns the whole screen, so there
    /// is no focus to consider and no mode to fall through to — one lookup, one
    /// action, and Esc is the way out.
    fn on_source_key(&mut self, key: KeyEvent) {
        // The message box is a pane that types, so it takes the keyboard whole
        // — a `k` in a commit message is the letter k.
        if self.git.focus == GitFocus::Message {
            return self.on_message_key(key);
        }
        let Some(action) = self.keymap.resolve(KeyContext::Source, &key) else {
            return;
        };
        // The global chords work here too: `Ctrl+P` is how `*commit` is typed,
        // and a window you cannot run a command from is a window with a hole
        // in it.
        if self.on_global_action(action) {
            return;
        }
        match action {
            Action::Up => self.move_git_cursor(-1),
            Action::Down => self.move_git_cursor(1),
            Action::Left => self.move_git_button(-1),
            Action::Right => self.move_git_button(1),
            Action::Open => self.activate_git(),
            Action::SourceOpen => self.open_from_git(),
            Action::Refresh => {
                self.refresh_git();
                self.status = "asked git again".into();
            }
            Action::PageUp => self.page_git_diff(-1),
            Action::PageDown => self.page_git_diff(1),
            Action::Narrower => self.resize_tree_pane(-1),
            Action::Wider => self.resize_tree_pane(1),
            Action::Back => self.show_window(Window::Main),
            _ => {}
        }
    }

    /// Which window this key asks for, if it asks for one.
    ///
    /// Read with [`resolve_while_typing`](crate::config::keys::Keymap::resolve_while_typing)
    /// so that, if someone binds a window to a bare letter, that letter is
    /// still a letter in a file or a commit message.
    fn window_key(&self, key: &KeyEvent) -> Option<Window> {
        // While the keybinds window is waiting for a key, every key is data —
        // these included, or nothing could ever be bound to them.
        if matches!(&self.mode, Mode::Keybinds(kb) if kb.capturing) {
            return None;
        }
        let typing = matches!(self.mode, Mode::Bar(_) | Mode::Settings(_))
            || (self.window == Window::Main
                && self.focus == Focus::Editor
                && matches!(self.preview, Preview::Buffer { .. }))
            || (self.window == Window::Source && self.git.focus == GitFocus::Message);
        let action = if typing {
            self.keymap.resolve_while_typing(KeyContext::Global, key)
        } else {
            self.keymap.find(KeyContext::Global, key)
        };
        match action {
            Some(Action::WindowSource) => Some(Window::Source),
            Some(Action::WindowMap) => Some(Window::Map),
            _ => None,
        }
    }

    /// The window keys are toggles: the key for the window you are in takes
    /// you back to the browser, so one key opens git and the same key puts it
    /// away — the way the browser's own key folds it and brings it back.
    fn toggle_window(&mut self, window: Window) {
        if self.window == window {
            self.show_window(Window::Main);
        } else {
            self.show_window(window);
        }
    }

    /// Arrows scroll the keymap; anything else puts it away.
    fn on_help_key(&mut self, scroll: usize, key: KeyEvent) {
        let page = self.last_tree_height.max(1);
        // No last row to clamp to here: `ui` knows how long the keymap is and
        // clamps as it draws.
        let Some(next) = list_move(key, scroll, usize::MAX, page) else {
            return;
        };
        self.mode = Mode::Help(next);
    }

    /// Forward a key to the map and act on what it asks for. The view
    /// handles its own navigation; only opening a file and closing the map
    /// need application state.
    fn on_map_key(&mut self, key: KeyEvent) {
        // The global chords work here too, and so does the bare `/` that
        // opens the bar: the map's filter is the bar, drawn where it always
        // is. Checked before the map's own keys, like everywhere else.
        if let Some(action) = self.keymap.find(KeyContext::Global, &key)
            && self.on_global_action(action)
        {
            return;
        }
        // Resolved here rather than inside the view: the map does not need to
        // know how a key becomes an action, only which one it was.
        let action = self.keymap.find(KeyContext::Map, &key);
        let intent = match self.project_map.as_mut() {
            Some(view) => view.on_key(action),
            None => return,
        };
        match intent {
            Intent::None => {}
            Intent::Close => {
                self.show_window(Window::Main);
                return;
            }
            Intent::Open(path) => {
                self.window = Window::Main;
                self.open_path(&path);
                return;
            }
            Intent::Rebuild => {
                // Same path as opening it, so a rebuilt map is indistinguishable
                // from a freshly opened one.
                self.open_map();
                return;
            }
        }
        // The counts move as filters change, so keep them in front of you.
        if let Some(view) = self.project_map.as_ref() {
            self.status = format!("project map — {}", view.summary());
        }
    }

    /// Every action in [`KeyContext::Global`] that means the same thing
    /// wherever you are, in one place.
    ///
    /// These are the controls that have to work while you are typing into a
    /// file, which is what makes them chords: `f` is the letter f in the
    /// editor and cannot be anything else, so search is `Ctrl+F` there, with
    /// the bare `/` beside it for the panes where nothing is being typed.
    ///
    /// Handled here rather than twice, because a global that the tree and the
    /// editor disagreed about would not be global. Returns whether the action
    /// was one of them; [`Action::Save`] is deliberately not, since what it
    /// saves depends on where you are. The two window keys are not either:
    /// [`App::handle_key`] answers them before any pane is asked.
    fn on_global_action(&mut self, action: Action) -> bool {
        match action {
            Action::Quit => self.request_quit(),
            Action::Bar => self.open_bar(),
            Action::ToggleTreePane => self.toggle_tree_pane(),
            Action::NewWindow => self.open_new_window(),
            Action::Copy => self.copy_selection(),
            Action::Paste => self.paste_clipboard(),
            Action::Help => self.mode = Mode::Help(0),
            _ => return false,
        }
        true
    }

    /// Keys for the tree pane.
    ///
    /// Single letters are free here — unlike the editor, nothing is being
    /// typed — which is why the browser's own keys are bare: `.` for dotfiles,
    /// `<` and `>` for its width, `i` `j` `k` `l` for the arrows.
    ///
    /// Esc is `back` here as it is everywhere, and back from the browser is
    /// out of tiny — asking first if anything is unsaved.
    fn on_tree_key(&mut self, key: KeyEvent) {
        let page = self.last_tree_height.saturating_sub(1).max(1) as isize;
        let Some(action) = self.keymap.resolve(KeyContext::Tree, &key) else {
            return;
        };
        if self.on_global_action(action) {
            return;
        }
        match action {
            Action::Save => self.save_from_tree(),
            Action::Back => self.request_quit(),
            Action::Up => self.move_selection(-1),
            Action::Down => self.move_selection(1),
            Action::First => self.select_index(0),
            Action::Last => self.select_index(usize::MAX),
            Action::PageUp => self.move_selection(-page),
            Action::PageDown => self.move_selection(page),
            Action::Open => self.toggle_or_open(),
            Action::Right => self.activate(),
            Action::Left => self.collapse_or_parent(),
            Action::TreeHidden => self.toggle_hidden(),
            Action::Narrower => self.resize_tree_pane(-1),
            Action::Wider => self.resize_tree_pane(1),
            _ => {}
        }
    }

    /// Keys for the preview pane.
    ///
    /// The escape hatches come first and return early, so nothing that leaves
    /// the pane or acts on the file can be swallowed as text input. That is
    /// why every one of them is a chord, or Esc: a bare `/` in the editor is a
    /// slash being typed.
    ///
    /// Below that the function forks on whether there is a buffer behind the
    /// preview: a text file types, a picture scrolls.
    fn on_editor_key(&mut self, key: KeyEvent) {
        let tab_width = self.config.tab_width;
        let page = self.last_edit_height.saturating_sub(1).max(1);

        // Keys that leave the pane or act on the file come first, so they can
        // never be swallowed as text input. Everything global reaches here,
        // which is the point of the chords: `Ctrl+F` searches from inside the
        // editor, where a bare `/` is a slash and always will be. A buffer is
        // being typed into; a picture or a folder listing is not, and in front
        // of one a bare `/` should still open the bar.
        let resolved = if matches!(self.preview, Preview::Buffer { .. }) {
            self.keymap.resolve_while_typing(KeyContext::Editor, &key)
        } else {
            self.keymap.resolve(KeyContext::Editor, &key)
        };
        match resolved {
            Some(Action::Save) => return self.save_active(),
            // "Back to the tree" means the tree, even when it is folded away,
            // so it brings the pane back rather than handing the keyboard to
            // something that is not on screen.
            Some(Action::Back) => {
                self.focus_tree();
                self.status = "back to tree".into();
                return;
            }
            // The guard does the work: `on_global_action` runs the action if
            // it recognizes it and says so, and an action it does not
            // recognize falls through to the editing keyboard below.
            Some(action) if self.on_global_action(action) => return,
            _ => {}
        }

        // A picture, a directory listing, a binary: nothing to type into, so
        // the arrows move the view instead of a cursor.
        if !matches!(self.preview, Preview::Buffer { .. }) {
            return self.on_view_key(key, page);
        }

        // Read what the key meant before borrowing the buffer, so nothing has
        // to be cloned to satisfy the borrow checker on every keystroke.
        let action = self.keymap.find(KeyContext::Editor, &key);
        let Some(ed) = self.active_buffer_mut() else {
            self.focus = Focus::Tree;
            return;
        };
        if let Some(complaint) = edit_with_key(ed, action, key, page, tab_width) {
            self.status = complaint.into();
        }
    }

    /// Looking at something with no text behind it — a picture, a directory,
    /// a binary. Arrows scroll the view, because there is no cursor to move.
    ///
    /// The one place `preview_scroll` is driven by the keyboard. A text file
    /// never lands here: it has a buffer, and the buffer has a cursor.
    fn on_view_key(&mut self, key: KeyEvent, page: usize) {
        let max = self.preview_len.saturating_sub(1);
        let Some(action) = self.keymap.find(KeyContext::View, &key) else {
            return;
        };
        match action {
            Action::Up => self.preview_scroll = self.preview_scroll.saturating_sub(1),
            Action::Down => self.preview_scroll = (self.preview_scroll + 1).min(max),
            Action::First => self.preview_scroll = 0,
            Action::Last => self.preview_scroll = max,
            Action::PageUp => self.preview_scroll = self.preview_scroll.saturating_sub(page),
            Action::PageDown => self.preview_scroll = (self.preview_scroll + page).min(max),
            _ => {}
        }
    }

    /// One notch of the mouse wheel, over the pane at `column`.
    ///
    /// Always exactly one line. The wheel is the one input where a terminal
    /// will happily send three of something for one flick of a finger, and a
    /// note that jumps three lines at a time is hard to read against.
    ///
    /// What "one line" means depends on the pane. A rendered note or a picture
    /// has no cursor, so the view itself moves. The editor does have one, and
    /// its view is tied to it, so the cursor moves instead — which scrolls the
    /// view once it reaches an edge, and never leaves you looking at somewhere
    /// you cannot type.
    pub fn on_scroll(&mut self, down: bool, column: u16) {
        let step: isize = if down { 1 } else { -1 };
        if self.over_tree(column) {
            // The preview follows the tree cursor, so moving the view on its
            // own would only be undone on the next frame.
            self.move_selection(step);
            return;
        }
        // A file being edited has a cursor and a view tied to it; anything
        // else is just a picture of something, and the view itself moves.
        if !matches!(self.preview, Preview::Buffer { .. }) || self.focus != Focus::Editor {
            let max = self.preview_len.saturating_sub(1);
            self.preview_scroll = if down {
                (self.preview_scroll + 1).min(max)
            } else {
                self.preview_scroll.saturating_sub(1)
            };
        } else if let Some(ed) = self.active_buffer_mut() {
            if down {
                ed.move_down();
            } else {
                ed.move_up();
            }
        }
    }

    /// Whether `column` fell inside the tree pane as it was last drawn.
    ///
    /// False whenever the tree is not on screen, which covers both `Ctrl+Space`
    /// and the very first frame, before `ui` has said where anything is.
    fn over_tree(&self, column: u16) -> bool {
        matches!(self.last_tree_cols, Some((x0, x1)) if column >= x0 && column < x1)
    }
}

