#[test]
fn ctrl_f_opens_the_search_and_a_star_turns_it_into_a_command() {
    let (_td, mut app) = fixture();
    editing(&mut app);
    app.on_key(ctrl('f'));
    let Mode::Bar(b) = &app.mode else {
        panic!("the bar should have opened from the editor")
