    select(&mut app, "Makefile");

    let out = joined(&mut app);
    assert!(
        out.contains("    echo hello"),
        "the tab reached its stop:\n{out}"
    );
    assert!(
        !out.contains(" echo hello") || out.contains("    echo hello"),
        "and did not collapse to nothing:\n{out}"
    );
}

