//! Noticing that the disk has changed underneath us.
//!
//! Another program writes to a file tiny has open — a formatter, a build step,
//! a `git checkout`, the same project open in another window — and what is on
//! screen is now a picture of a file that no longer exists. This is the part
//! that fixes that: [`App::rescan_disk`] is called by the event loop whenever
//! it has been idle for a moment, and takes on whatever it finds.
//!
//! # Polling, not inotify
//!
//! There is no watcher and no background thread. The event loop waits on the
//! keyboard with a timeout instead of without one, and every time the timeout
//! expires it stats what is on screen: the directories the tree has read, and
//! the files there are buffers for. That is a handful of `stat` calls twice a
//! second — microseconds — against a dependency, a thread, a channel, and a
//! way to wake a blocking read, which is what a real watcher would cost.
//!
//! The trade is honest and worth naming: tiny is no longer a program that uses
//! *no* CPU while idle. It uses a rounding error of one.
//!
//! # Stamps are taken when the thing is read, not when it is scanned
//!
//! Every path is remembered as its modification time and size, and the stamp
//! is taken at the moment tiny reads the thing: [`App::note_file`] when a
//! buffer is opened, [`App::note_dirs`] whenever the tree has been rebuilt.
//!
//! Doing it at the first *scan* instead would leave a hole exactly the width
//! of the poll interval. Expand a folder, have a file land in it 200ms later,
//! and the first scan would record a modification time that already includes
//! the new file without ever having drawn it — so it would stay invisible
//! until something else changed in that folder.
//!
//! A path with no stamp at all is still recorded rather than acted on, which
//! is what keeps the scan after startup from deciding the whole project has
//! just changed.
//!
//! # Our own writes
//!
//! Saving from tiny moves the file's modification time as surely as anyone
//! else's write does, so the next scan sees a difference on a file we just
//! wrote ourselves. Rather than trying to remember which writes were ours,
//! a file whose stamp moved is read and compared: identical text is not a
//! change, and nothing on screen moves. It costs one read of a file small
//! enough to be open in an editor, and only on the scan after a write.
//!
//! # A stamp can be too young to trust
//!
//! Some filesystems keep coarse time: NTFS moves in steps of about sixteen
//! milliseconds, HFS+ in one second, FAT in two. Two changes inside one step
//! leave the same stamp, so a scan that fell between them would see nothing
//! for the second. A stamp younger than [`RACY`] is therefore a reason to look
//! rather than proof that nothing moved — a folder is re-read, a clean file
//! re-read and compared — and neither draws a frame unless something did.
//!
//! # Unsaved work is never overwritten
//!
//! A dirty buffer is never reloaded, whatever the disk says. It gets a line on
//! the status bar — once, because the stamp is updated either way — and keeps
//! the text the user typed. There is nowhere else for that text to live.

use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::time::{Duration, SystemTime};

use super::App;
use super::mode::Focus;
use super::parts::display_name;
use super::preview::Preview;

/// What a path looked like when we last stat'd it: modification time and size.
///
/// `None` records that it could not be stat'd at all, which is a state like
/// any other — going from `Some` to `None` is a file being deleted, and going
/// the other way is one appearing.
type Stamp = Option<(SystemTime, u64)>;

/// Both halves of what tiny is looking at, as of the last scan.
///
/// Kept in the same shape for directories and files even though they are
/// checked for different things: a directory's modification time changes when
/// an entry is added or removed, a file's when its contents are written.
#[derive(Debug, Default)]
pub struct Watch {
    dirs: HashMap<PathBuf, Stamp>,
    files: HashMap<PathBuf, Stamp>,
}

/// Modification time and size, or `None` for anything that cannot be stat'd.
///
/// A filesystem with no usable modification time still gets its size watched,
/// which catches most edits — better than a stamp that can never differ.
fn stamp(path: &Path) -> Stamp {
    let m = fs::metadata(path).ok()?;
    Some((m.modified().unwrap_or(SystemTime::UNIX_EPOCH), m.len()))
}

/// How long after a change a stamp cannot be trusted to have caught the next.
///
/// This is git's "racily clean" problem — a timestamp is only as fine as the
/// clock that wrote it — and the answer is git's: a stamp too young to vouch
/// for itself is a reason to look. Two seconds covers the coarsest filesystem
/// anyone is likely to open a project on.
const RACY: Duration = Duration::from_secs(2);

/// Whether this stamp is too recent to prove nothing has changed since.
fn racy(stamp: &Stamp) -> bool {
    match stamp {
        Some((when, _)) => match SystemTime::now().duration_since(*when) {
            Ok(age) => age < RACY,
            // A time in the future — clock skew, a network share — cannot
            // vouch for anything either.
            Err(_) => true,
        },
        None => false,
    }
}

impl App {
    /// Remember what the directories on screen look like right now.
    ///
    /// Called from `rebuild_rows`, which runs after every structural change to
    /// the tree, so the stamps are always as fresh as the rows drawn from them.
    pub(super) fn note_dirs(&mut self) {
        self.watch.dirs = self
            .tree
            .loaded_dirs()
            .into_iter()
            .map(|d| {
                let now = stamp(&d);
                (d, now)
            })
            .collect();
    }

    /// Remember what a file looked like as it was read into a buffer.
    pub(super) fn note_file(&mut self, path: &Path) {
        let now = stamp(path);
        self.watch.files.insert(path.to_path_buf(), now);
    }

    /// Take on everything that changed on disk since the last look. Returns
    /// whether anything did, which is the event loop's cue to draw a frame.
    ///
    /// Directories first, so that a file which has just been deleted is
    /// already out of the tree by the time its buffer is dealt with.
    pub fn rescan_disk(&mut self) -> bool {
        if !self.config.auto_reload {
            return false;
        }
        let dirs = self.rescan_dirs();
        let files = self.rescan_files();
        dirs || files
    }

    /// Entries appearing in or disappearing from the directories on screen.
    ///
    /// One stat per directory the tree has read; collapsed ones are not read,
    /// so a project with a large unopened subtree costs nothing to watch. Any
    /// difference re-reads the lot, because [`Tree::refresh_all`] is cheap
    /// relative to the drawing that follows it and the alternative is a
    /// per-directory merge that would have to reimplement it.
    ///
    /// [`Tree::refresh_all`]: crate::files::tree::Tree::refresh_all
    fn rescan_dirs(&mut self) -> bool {
        let mut changed = false;
        let mut fresh: HashMap<PathBuf, Stamp> = HashMap::new();
        for dir in self.tree.loaded_dirs() {
            let now = stamp(&dir);
            changed |= self
                .watch
                .dirs
                .get(&dir)
                .is_some_and(|was| *was != now || racy(was));
            fresh.insert(dir, now);
        }
        self.watch.dirs = fresh;
        if !changed {
            return false;
        }
        // `rebuild_rows` re-derives the preview, which resets its scroll. That
        // is right when the cursor has moved to another file and wrong when it
        // has not — a file being written elsewhere in the project should not
        // send you back to the top of the one you are reading.
        let before: Vec<PathBuf> = self.rows.iter().map(|r| r.path.clone()).collect();
        let was_on = self.selected_path().map(Path::to_path_buf);
        let scroll = self.preview_scroll;
        self.tree.refresh_all();
        self.rebuild_rows();
        if was_on.as_deref() == self.selected_path() {
            self.preview_scroll = scroll;
        } else if self.focus == Focus::Editor {
            // The row the keyboard was in has gone, and the cursor has fallen
            // onto a neighbor. Take the keyboard out of the file: otherwise
            // the next thing typed is typed into whichever file that turned
            // out to be. What happened to the file itself is `take_on_disk`'s
            // to say.
            self.focus_tree();
        }
        // A racy stamp is a reason to look, not proof that anything moved, and
        // looking and finding the same listing is not worth a frame.
        !self.rows.iter().map(|r| &r.path).eq(before.iter())
    }

    /// Open files whose contents have been written by someone else.
    fn rescan_files(&mut self) -> bool {
        let mut changed = false;
        for path in self.buffers.keys().cloned().collect::<Vec<_>>() {
            let now = stamp(&path);
            let dirty = self.is_dirty(&path);
            match self.watch.files.get(&path) {
                // Unchanged — unless the stamp is too young to prove it. Then a
                // clean buffer is read and compared, which costs one read and
                // says nothing when nothing changed. A dirty one is not: its
                // warning is given once per real change, not once per tick.
                Some(was) if *was == now && (dirty || !racy(was)) => continue,
                Some(_) => {
                    self.watch.files.insert(path.clone(), now);
                    changed |= self.take_on_disk(&path);
                }
                // Never seen before: this is the scan that learns it, not the
                // one that acts on it.
                None => {
                    self.watch.files.insert(path, now);
                }
            }
        }
        // A buffer can go away — a delete, or a rename moving it to another
        // key — and its stamp should not outlive it.
        let buffers = &self.buffers;
        self.watch.files.retain(|p, _| buffers.contains_key(p));
        changed
    }

    /// One file that is no longer what it was. Returns whether the screen
    /// needs redrawing.
    fn take_on_disk(&mut self, path: &Path) -> bool {
        let name = display_name(path);
        let fresh = fs::read(path)
            .ok()
            .and_then(|bytes| String::from_utf8(bytes).ok())
            // The same guard `load_file_preview` uses: a file that has become
            // binary is not text that happens to decode.
            .filter(|text| !text.contains('\0'));
        let dirty = self.is_dirty(path);

        let Some(text) = fresh else {
            // Deleted, unreadable, or no longer text.
            if dirty {
                // The buffer stays. There is no row to put the cursor back on,
                // but the text is not lost: it is still listed on the way out,
                // and saving it there writes the file back.
                self.status = format!("{name} is gone from disk — your unsaved copy is kept");
                return true;
            }
            let showing = matches!(&self.preview, Preview::Buffer { path: p, .. } if p == path);
            self.buffers.remove(path);
            self.highlight_cache.clear();
            // Dropping the buffer is what lets the file be classified afresh
            // if it comes back, since an open buffer always wins over disk.
            if showing {
                self.sync_preview();
            }
            self.status = format!("{name} is gone from disk");
            return true;
        };

        if dirty {
            self.status = format!("{name} changed on disk — your unsaved copy is what you see");
            return true;
        }
        let Some(editor) = self.buffers.get_mut(path) else {
            return false;
        };
        // Our own save, or someone else's write that changed nothing.
        if editor.to_text() == text {
            return false;
        }
        editor.reload_from(&text);
        // The cache holds parser state keyed by line number, and every line
        // number in this file has just been reconsidered.
        self.highlight_cache.clear();
        self.status = format!("{name} changed on disk — reloaded");
        true
    }
}

files.src/config/keys.rs:
//! Key bindings: what every key does, and how to change it.
//!
//! Every key tiny acts on is named. [`Action`] is the list of those names,
//! [`Keymap`] maps keys onto them, and the handlers in `app` ask the keymap
//! what a keypress meant instead of matching on the key itself. That
//! indirection is the whole feature: a binding can then come from a config
//! file or from the keybinds window, without a single `match` arm moving.
//!
//! # What is not bindable
//!
//! Keys that put a character into a file or a field are not here, and cannot
//! be. In the editor, the bar, and every prompt, `n` is the letter n — there is
//! no binding to change, because the key is not a command. The same goes for
//! the text-editing primitives beside them: the arrows, `Backspace`, `Delete`,
//! `Enter` and `Tab` move and edit text while you are typing into it, and
//! rebinding those would leave a keyboard that cannot type.
//!
//! Everything else — the browser, a note being read, the project map, the git
//! window, and every chord that reaches out of the pane you are in — is
//! bindable.
//!
//! # Contexts
//!
//! The same key means different things in different panes: `k` is *down* in the
//! browser and the letter k in the editor. [`Context`] says which set of
//! actions a keypress is being read against. The chords in [`Context::Global`]
//! are checked first everywhere, which is why `Ctrl+S` saves from wherever you
//! are.
//!
//! An action lists the panes it works in, and most movements work in several.
//! Moving up is one action, `up`, bound to one key; the browser, a note being
//! read, the map and the git window each answer it in their own way. `open` is
//! the same idea for Enter: it opens a file in the browser and on the map, and
//! stages one in the git window — one row to find, and one key to rebind.
//!
//! Everything in `Global` that has to work while you type is a chord. In the
//! editor a letter is a letter being typed, so a control that must work there
//! has no other shape available. A global may *also* carry a bare key, like
//! `/` beside `Ctrl+F`: [`Keymap::resolve_while_typing`] skips the bare one in
//! a pane that types, so it costs nothing there and saves a chord everywhere
//! else.
//!
//! # What is a key and what is a command
//!
//! Not everything tiny does is here, and that is the point. Keys are for
//! moving around and for changing a file: things done constantly, in the middle
//! of something else, where a key is the only shape fast enough. Deleting a
//! path, re-reading the disk, opening the settings — those are deliberate acts,
//! usually with something to type after them, and they are commands (`*delete`,
//! `*reload`, `*config`).
//!
//! # Every key arrives on every terminal
//!
//! A binding that some terminals never deliver is worse than none: the help
//! window promises it, and on the wrong machine nothing happens — or something
//! else does. So the shipped keyboard is made only of keys that arrive as
//! themselves on macOS Terminal, iTerm2, Windows Terminal and the usual Linux
//! emulators, with their stock settings:
//!
//! - **Ctrl and a letter.** Every terminal sends these, in raw mode, as
//!   themselves — except `Ctrl+H`, `Ctrl+I`, `Ctrl+J` and `Ctrl+M`, which *are*
//!   Backspace, Tab and Enter in the encoding, and `Ctrl+B`, which tmux keeps
//!   for its prefix. None of those five is bound.
//! - **Plain keys** — letters, `/`, `?`, `.`, the arrows, Enter, Esc, Tab — in
//!   the panes where nothing is being typed.
//!
//! What is *not* shipped, and why:
//!
//! - **Ctrl with a digit or a punctuation mark.** Not in a terminal's legacy
//!   encoding at all: `Ctrl+1` sends nothing, `Ctrl+2` arrives as `Ctrl+Space`
//!   and `Ctrl+3` as `Esc` — which, in the browser, used to quit.
//! - **Function keys.** On a Mac they are brightness and Mission Control unless
//!   Fn is held, and GNOME Terminal keeps `F1` for its own help. `F1` is still
//!   bound beside `?`, because on a PC keyboard it is where people look first.
//! - **Ctrl with an arrow.** macOS switches Spaces on `Ctrl+←` and `Ctrl+→`,
//!   and opens Mission Control on `Ctrl+↑` — the terminal never sees them.
//!   They stay bound in the editor beside a twin that a Mac does send, for the
//!   PC keyboards that expect them.
//! - **Ctrl+Space.** macOS switches input source on it.
//! - **Home, End, Page Up, Page Down** as the *only* way to do something. A
//!   MacBook has none of them, and Terminal uses all four to scroll its own
//!   history unless Shift is held. Each is bound beside a chord that works
//!   everywhere: `Ctrl+A` and `Ctrl+E` for the ends of a line, the way every
//!   Mac text field and every shell already does it, and `Ctrl+U` and `Ctrl+D`
//!   for a screen at a time, the way `less` and `vim` do.
//!
//! The one key a terminal takes for itself is `Ctrl+V`: Windows Terminal and
//! the Windows console paste on it before the program sees anything. That is
//! the whole of [`Keyboard`] — on Windows, file paste ships on `Ctrl+P`.
//!
//! # Option and the arrows
//!
//! On a Mac, `⌥←` and `⌥→` are how a word is skipped, and the terminals do not
//! agree on how to say so: iTerm2 sends them as `Alt` with an arrow, and macOS
//! Terminal sends the `Esc b` and `Esc f` that a shell's readline expects —
//! `Alt+B` and `Alt+F`. [`super::keyspec::from_terminal`] turns the second
//! spelling into the first before anything else looks at the key, so one
//! binding, `alt+left`, answers both.
//!
//! # One key per thing
//!
//! Two keys that do the same thing are one key and one thing to remember for
//! nothing, so the only second keys are ones that stand in for a key some
//! keyboards lack: `i` `j` `k` `l` for the arrows, `I` and `K` for Home and
//! End, the chords above for the Mac. And two *actions* that do the same thing
//! are worse, because each is a row to read past; the browser's Tab, which did
//! what Enter does, is gone, and so are the five-line jumps that a screen at a
//! time already covered.
//!
//! # Defaults and overrides
//!
//! [`Action::defaults`] is the shipped keyboard, written out in one table. The
//! config file holds *only* what differs from it, so an untouched `tiny.conf`
//! has no `[keys]` section at all and a new default reaches everyone who has
//! not overridden that action. Resetting is therefore just dropping the
//! overrides. Names that have changed are carried over by [`migrate`], so a
//! config written by an older tiny keeps meaning what it meant.

use std::collections::BTreeMap;
use std::fmt::Write as _;

pub use super::keyspec::{Key, from_terminal, spec_of};
use crossterm::event::KeyEvent;

/// Which set of actions a keypress is read against.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Context {
    /// Chords that work from any pane. Checked before the pane's own set.
    Global,
    Tree,
    /// A preview with no text buffer behind it — a picture, a directory, a
    /// binary. There is nothing to type into, so the arrows scroll the view.
    View,
    /// The editor, and the one key that leaves it.
    Editor,
    Map,
    /// The source-control window: the change list and its buttons.
    Source,
}

impl Context {
    pub fn title(self) -> &'static str {
        match self {
            Context::Global => "ANYWHERE",
            Context::Tree => "BROWSER",
            Context::View => "VIEWING",
            Context::Editor => "EDITOR",
            Context::Map => "MAP",
            Context::Source => "GIT",
        }
    }
}

/// Which keys the terminal keeps for itself.
///
/// One key differs, and only on Windows: Windows Terminal, and the Windows
/// console with its Ctrl shortcuts on, paste the clipboard on `Ctrl+V` before
/// tiny sees the key — so a file paste there ships on `Ctrl+P`, which reaches
/// the program. Everything else is the same keyboard everywhere.
///
/// Decided once, by [`Keyboard::detect`] in `main`, and passed in rather than
/// looked up inside the keymap, so the tests can build either keyboard on any
/// machine.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum Keyboard {
    #[default]
    Standard,
    /// Windows Terminal — native, or under WSL — or the Windows console.
    Windows,
}

/// What changes on [`Keyboard::Windows`]. Substitutions, not additions: the
/// `Ctrl+V` that would never arrive is not listed, because a key the keybinds
/// window shows is a key that works.
const WINDOWS_KEYS: &[(Action, &str)] = &[(Action::Paste, "ctrl+p")];

impl Keyboard {
    /// Which keyboard this terminal gets.
    ///
    /// A native Windows build always runs in a Windows terminal. Under WSL the
    /// program is a Linux one, so the terminal has to say so itself: Windows
    /// Terminal sets `WT_SESSION`, and passes it through to WSL.
    pub fn detect() -> Self {
        if cfg!(windows) || std::env::var_os("WT_SESSION").is_some() {
            Keyboard::Windows
        } else {
            Keyboard::Standard
        }
    }

    /// The keys `action` ships with on this keyboard.
    pub fn defaults(self, action: Action) -> &'static str {
        if self == Keyboard::Windows
            && let Some((_, keys)) = WINDOWS_KEYS.iter().find(|(a, _)| *a == action)
        {
            return keys;
        }
        action.defaults()
    }
}

