#[cfg(test)]
mod tests {
    use super::*;

    /// Package names in `Cargo.lock`, which is the whole dependency graph
    /// including the ones only the tests use.
    fn locked() -> Vec<String> {
        include_str!("../Cargo.lock")
            .lines()
            .filter_map(|l| l.strip_prefix("name = \""))
            .filter_map(|l| l.strip_suffix('"'))
            .map(str::to_string)
            .collect()
    }

    #[test]
    fn every_listed_crate_is_one_we_actually_depend_on() {
        let locked = locked();
        for (name, _) in CRATES {
            assert!(
                locked.iter().any(|l| l == name),
                "{name} is listed as a dependency but is not in Cargo.lock"
            );
        }
    }

    #[test]
    fn every_dependency_we_ship_is_listed() {
        // The direct ones, read from the manifest rather than written down
        // again here: a crate added to `[dependencies]` and not to `CRATES`
        // is the mistake this is looking for.
        let manifest = include_str!("../Cargo.toml");
        let deps = manifest
            .split("[dependencies]")
            .nth(1)
            .expect("a dependencies section")
            .split("\n[")
            .next()
            .expect("the section ends");
        for line in deps.lines() {
            let Some(name) = line.split_whitespace().next() else {
                continue;
            };
            if name.is_empty() || name.starts_with('#') {
                continue;
            }
            assert!(
                CRATES.iter().any(|(c, _)| *c == name),
                "{name} is a dependency but is not in CRATES — see the module docs"
            );
        }
    }

    #[test]
    fn the_list_is_sorted_and_says_each_name_once() {
        let names: Vec<&str> = CRATES.iter().map(|(n, _)| *n).collect();
        let mut sorted = names.clone();
        sorted.sort_unstable();
        sorted.dedup();
        assert_eq!(names, sorted, "CRATES should be sorted, with no repeats");
    }

    #[test]
    fn nothing_in_the_binary_is_copyleft() {
        // The whole reason tiny can be MIT. A GPL crate would make this a
        // licensing decision rather than a listing, so it should fail loudly
        // the moment one arrives.
        for (name, license) in CRATES {
            let l = license.to_ascii_uppercase();
            for bad in ["GPL", "AGPL", "LGPL", "MPL", "EUPL", "CDDL"] {
                assert!(!l.contains(bad), "{name} is {license}");
            }
        }
    }

    #[test]
    fn the_notice_carries_all_three_layers() {
        let out = notice();
        assert!(out.contains("MIT License"), "tiny's own terms");
        assert!(out.contains("ratatui"), "the crates it is built from");
        assert!(
            out.contains("Lua.org, PUC-Rio"),
            "Lua, built in from source"
        );
        assert!(out.contains("syntax definitions"), "the bundled grammars");
    }

    // ---- the notices file --------------------------------------------------

    const NOTICES: &str = include_str!("../THIRD-PARTY-NOTICES.txt");

    /// Each crate's entry in the notices: its name, and the license line under
    /// it. An entry is a line with nothing in front of it, in the crates part.
    ///
    /// Line endings are made one kind first: git on Windows checks the file
    /// out with `\r\n`, and a `\r` left at the end of the part was read as
    /// one more crate, with no name.
    fn entries() -> Vec<(String, String)> {
        let notices = NOTICES.replace("\r\n", "\n");
        let crates = notices
            .split("---- crates ")
            .nth(1)
            .expect("a crates part")
            .split("\n---- ")
            .next()
            .expect("it ends");
        let lines: Vec<&str> = crates.lines().skip(1).collect();
        lines
            .iter()
            .enumerate()
            .filter(|(_, l)| !l.trim().is_empty() && !l.starts_with(' '))
            .map(|(i, l)| {
                let name = l.split_whitespace().next().unwrap_or("").to_string();
                let license = lines
                    .get(i + 1)
                    .and_then(|l| l.trim().strip_prefix("license: "))
                    .unwrap_or("")
                    .to_string();
                (name, license)
            })
            .collect()
    }

    #[test]
    fn the_notices_name_every_crate_and_nothing_else() {
        let entries = entries();
        let named: Vec<&str> = entries.iter().map(|(n, _)| n.as_str()).collect();
        let listed: Vec<&str> = CRATES.iter().map(|(n, _)| *n).collect();
        assert_eq!(
            named, listed,
            "THIRD-PARTY-NOTICES.txt is out of date — run \
             `cargo test write_third_party_notices -- --ignored`"
        );
        for ((name, said), (_, declared)) in entries.iter().zip(CRATES) {
            assert!(
                said.starts_with(declared),
                "{name}: the notices say `{said}`, the crate says `{declared}`"
            );
        }
    }

    #[test]
    fn every_license_taken_has_its_text_in_the_notices() {
        for (name, said) in entries() {
            let taken = said.rsplit("taken as ").next().unwrap_or(&said).to_string();
            for id in taken.split(" and ") {
                assert!(
                    NOTICES
                        .replace("\r\n", "\n")
                        .contains(&format!("\n---- {id} ")),
                    "{name} is taken under {id}, whose text is not in the notices"
                );
            }
        }
    }

    // ---- writing it -------------------------------------------------------

    /// Which of the licenses a crate offers tiny takes.
    ///
    /// MIT wherever it is offered: the shortest text, and the one tiny is
    /// under itself. Otherwise anything but Apache-2.0, whose text is longer
    /// than most of the crates it would cover. An `AND` takes every part.
    fn taken(expression: &str) -> Vec<String> {
        expression
            .split(" AND ")
            .map(|part| {
                let part = part.trim().trim_start_matches('(').trim_end_matches(')');
                let offered: Vec<&str> = part
                    .split(" OR ")
                    .flat_map(|o| o.split('/'))
                    .map(str::trim)
                    .collect();
                let pick = if offered.contains(&"MIT") {
                    "MIT"
                } else {
                    offered
                        .iter()
                        .find(|o| !o.starts_with("Apache-2.0"))
                        .unwrap_or(&offered[0])
                };
                pick.to_string()
            })
            .collect()
    }

    /// The file in a crate's folder that holds the text of `license`.
    fn license_file(dir: &std::path::Path, license: &str) -> Option<String> {
        let mut names: Vec<String> = std::fs::read_dir(dir)
            .ok()?
            .flatten()
            .map(|e| e.file_name().to_string_lossy().into_owned())
            .filter(|n| {
                let u = n.to_uppercase();
                u.starts_with("LICEN") || u.starts_with("COPYING")
            })
            .collect();
        names.sort();
        let marker = match license {
            "MIT" => "MIT",
            "BSL-1.0" => "BOOST",
            "Zlib" => "ZLIB",
            "Unicode-3.0" => "UNICODE",
            other => other,
        };
        let read = |n: &String| std::fs::read_to_string(dir.join(n)).ok();
        // A file named for the license, or the one plain LICENSE when that is
        // the license it holds.
        names
            .iter()
            .find(|n| n.to_uppercase().contains(marker))
            .and_then(read)
            .or_else(|| {
                names
                    .iter()
                    .filter(|n| {
                        let u = n.to_uppercase();
                        matches!(
                            u.as_str(),
                            "LICENSE" | "LICENCE" | "LICENSE.MD" | "LICENSE.TXT"
                        )
                    })
                    .filter_map(read)
                    .find(|text| license != "MIT" || text.contains("Permission is hereby granted"))
            })
    }

    /// The copyright lines in a license's text, as written there.
    fn copyright_lines(text: &str) -> Vec<String> {
        text.lines()
            .map(|l| l.trim().trim_start_matches(['>', '*', '#', ' ']).trim())
            .filter(|l| {
                let lower = l.to_lowercase();
                lower.starts_with("copyright") || lower.starts_with("(c)") || l.starts_with('©')
            })
            // `[Name](https://...)` reads as `Name`.
            .map(|l| {
                let mut out = String::new();
                let mut rest = l;
                while let Some(open) = rest.find('[') {
                    match (rest[open..].find("]("), rest[open..].find(')')) {
                        (Some(mid), Some(close)) if mid < close => {
                            out.push_str(&rest[..open]);
                            out.push_str(&rest[open + 1..open + mid]);
                            rest = &rest[open + close + 1..];
                        }
                        _ => break,
                    }
                }
                out.push_str(rest);
                out
            })
            .collect()
    }

    /// One line, ruled out to a fixed width, that starts a part of the file.
    fn rule(title: &str) -> String {
        let head = format!("---- {title} ");
        let dashes = 76usize.saturating_sub(head.chars().count());
        format!("{head}{}\n", "-".repeat(dashes))
    }

    /// Rebuild `THIRD-PARTY-NOTICES.txt` from the crates' own license files.
    ///
    /// Skipped unless asked for, because it reads cargo's copy of every
    /// crate's source and writes into this one. Run it after changing
    /// dependencies and commit what it writes;
    /// `the_notices_name_every_crate_and_nothing_else` says when it is due.
    #[test]
    #[ignore]
    fn write_third_party_notices() {
        use std::collections::BTreeMap;
        use std::path::Path;

        let out = std::process::Command::new(env!("CARGO"))
            .args(["metadata", "--format-version", "1", "--locked"])
            .current_dir(env!("CARGO_MANIFEST_DIR"))
            .output()
            .expect("cargo metadata runs");
        let meta: serde_json::Value =
            serde_json::from_slice(&out.stdout).expect("cargo metadata speaks JSON");
        let packages = meta["packages"].as_array().expect("a list of packages");

        // tiny's own LICENSE, from the permission on: the MIT text, once, for
        // every crate taken under MIT.
        let own = include_str!("../LICENSE");
        let mit = &own[own
            .find("Permission is hereby granted")
            .expect("tiny is MIT")..];

        let mut texts: BTreeMap<String, Vec<(String, Vec<String>)>> = BTreeMap::new();
        let mut body = String::new();
        for (name, declared) in CRATES {
            let found: Vec<&serde_json::Value> =
                packages.iter().filter(|p| p["name"] == *name).collect();
            assert!(!found.is_empty(), "{name} is not in cargo metadata");
            let mut versions: Vec<&str> =
                found.iter().filter_map(|p| p["version"].as_str()).collect();
            versions.sort();
            let licenses = taken(declared);

            let mut copyright: Vec<String> = Vec::new();
            for p in &found {
                let dir = Path::new(p["manifest_path"].as_str().unwrap())
                    .parent()
                    .unwrap()
                    .to_path_buf();
                // The people the crate names as its authors, which is who holds
                // it when its own notice does not say.
                let authors: Vec<String> = p["authors"]
                    .as_array()
                    .into_iter()
                    .flatten()
                    .filter_map(|a| a.as_str())
                    .map(|a| a.split('<').next().unwrap_or(a).trim().to_string())
                    .filter(|a| !a.is_empty())
                    .collect();
                for license in &licenses {
                    let Some(text) = license_file(&dir, license) else {
                        continue;
                    };
                    // A line with a year and no one in it keeps its words and
                    // gains the crate's authors after them.
                    copyright.extend(copyright_lines(&text).into_iter().map(|line| {
                        let holder = line
                            .to_lowercase()
                            .replace("copyright", "")
                            .replace("(c)", "")
                            .replace(['©', '-', ',', ' '], "");
                        if !holder.chars().all(|c| c.is_ascii_digit()) {
                            line
                        } else if authors.is_empty() {
                            format!("{line} — the {name} developers")
                        } else {
                            format!("{line} — {}", authors.join(", "))
                        }
                    }));
                    if license != "MIT" {
                        let crates = texts.entry(license.clone()).or_default();
                        let same = |t: &String| t.split_whitespace().eq(text.split_whitespace());
                        match crates.iter_mut().find(|(t, _)| same(t)) {
                            Some((_, users)) => users.push(name.to_string()),
                            None => crates.push((text.trim().to_string(), vec![name.to_string()])),
                        }
                    }
                }
                if copyright.is_empty() {
                    copyright.push(if authors.is_empty() {
                        format!("Copyright (c) the {name} developers")
                    } else {
                        format!("Copyright (c) {}", authors.join(", "))
                    });
                }
            }
            copyright.dedup();
            let mut seen = Vec::new();
            copyright.retain(|c| {
                let fresh = !seen.contains(c);
                seen.push(c.clone());
                fresh
            });

            body.push_str(&format!("{name} {}\n", versions.join(", ")));
            let taken_as = licenses.join(" and ");
            if taken_as == *declared {
                body.push_str(&format!("    license: {declared}\n"));
            } else {
                body.push_str(&format!("    license: {declared}, taken as {taken_as}\n"));
            }
            for c in &copyright {
                body.push_str(&format!("    {c}\n"));
            }
            body.push('\n');
        }

        // Lua is C, built into the binary from the source lua-src carries,
        // and its notice is in that source rather than in any crate's file.
        let lua_src = packages
            .iter()
            .find(|p| p["name"] == "lua-src")
            .expect("lua-src builds Lua");
        let lua_dir = Path::new(lua_src["manifest_path"].as_str().unwrap())
            .parent()
            .unwrap()
            .to_path_buf();
        let lua54 = std::fs::read_dir(&lua_dir)
            .unwrap()
            .flatten()
            .map(|e| e.file_name().to_string_lossy().into_owned())
            .filter(|n| n.starts_with("lua-5.4"))
            .max()
            .expect("lua-src carries Lua 5.4");
        let lua_h = std::fs::read_to_string(lua_dir.join(&lua54).join("lua.h")).unwrap();
        let lua_copyright = copyright_lines(&lua_h)
            .into_iter()
            .find(|l| l.contains("Lua.org"))
            .expect("lua.h carries its notice");

        let mut file = String::new();
        file.push_str(
            "THIRD-PARTY NOTICES\n\n\
             tiny carries the work below inside its binary. Each crate is listed with\n\
             its copyright and the license it is offered under; where it offers a\n\
             choice, the one tiny takes is named. The text of each license follows\n\
             the list, once: the copyright notices above it are the ones it refers to.\n\n\
             Written from each crate's own license files by\n\
             `cargo test write_third_party_notices -- --ignored`.\n\n",
        );
        file.push_str(&rule("crates"));
        file.push('\n');
        file.push_str(&body);
        file.push_str(&rule("built in from source"));
        file.push('\n');
        file.push_str(&format!(
            "Lua {} (built by lua-src)\n    license: MIT\n    {lua_copyright}\n\n",
            lua54.trim_start_matches("lua-")
        ));
        // The themes syntect compiles in. Their notices are not in the crate;
        // these are from each theme's own LICENSE upstream: base16-textmate,
        // altercation/solarized and sethlopezme/InspiredGitHub.tmtheme.
        file.push_str(
            "Color themes bundled by syntect\n    license: MIT\n    \
             base16 (ocean, eighties, mocha): Copyright (C) 2012 Chris Kempson\n    \
             Solarized: Copyright (c) 2011 Ethan Schoonover\n    \
             InspiredGitHub: Copyright (c) 2015 Seth Lopez\n\n",
        );
        file.push_str(&rule("MIT"));
        file.push('\n');
        file.push_str(mit.trim());
        file.push_str("\n\n");
        for (license, versions) in &texts {
            for (text, users) in versions {
                file.push_str(&rule(&format!("{license} ({})", users.join(", "))));
                file.push('\n');
                file.push_str(text);
                file.push_str("\n\n");
            }
        }
        let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("THIRD-PARTY-NOTICES.txt");
        std::fs::write(&path, file.trim_end().to_string() + "\n").unwrap();
    }
}

files.src/main.rs:
//! tiny — a terminal knowledge manager.
//!
//! Left pane is the project tree, right pane is whatever the cursor is on:
//! markdown renders, code opens in an editor, pictures are described and
//! handed to the desktop's own viewer. `Ctrl+S` saves.
//!
//! # Where things live
//!
//! Reading top to bottom, the program is four layers:
//!
//! 1. **Startup** — this file. Parse the command line, work out what to open
//!    ([`files::project`]), load configuration ([`config`]), then hand control
//!    to a plain blocking event loop.
//! 2. **State** — [`app`]. One `App` struct owns everything mutable: the tree
//!    cursor, the open buffers, the current mode, the status line. Every
//!    keypress goes through `App::handle_key`.
//! 3. **Drawing** — [`ui`]. Reads `App` and paints a frame. It is deliberately
//!    the only module that knows about ratatui widgets.
//! 4. **Support** — three folders of self-contained machinery that `app` and
//!    `ui` call into: [`text`] (the buffer, markdown, highlighting, search),
//!    [`files`] (the tree, project resolution, media), and [`map`] (the link
//!    graph and the view of it), with [`parallel`] spreading the two
//!    whole-project jobs over every core. [`config`] holds the settings and
//!    the key bindings, and is read once before any of them. Beside them,
//!    [`plugins`] runs the Lua ones, [`update`] knows about new releases,
//!    and [`terminal`] opens another tiny in a window of its own.
//!
//! # The one-way rule
//!
//! State flows one way: keys mutate `App`, then `ui` reads `App` and draws.
//! `ui` never handles input, and `app` never touches a ratatui widget. The
//! sanctioned exceptions are all one thing: `ui` writes back scroll offsets
//! and the syntax-highlighting cache, because neither can be computed until
//! the pane size is known — and the pane size is only known while drawing.
//! `ui`'s own module docs list them. If you find yourself wanting another,
//! that is usually a sign the state belongs on `App` instead.
//!
//! # The event loop waits, and looks at the disk while it waits
//!
//! There is no background thread. `run` waits for the keyboard and redraws
//! once when something arrives, so nothing happens between keypresses that the
//! user did not cause — with one exception. The wait has a timeout, and each
//! time it expires the loop asks three questions: has anything on screen been
//! changed by another program (see [`app`'s disk watcher](app)), has a git
//! push or pull finished on its thread, and has the [`update`] check come
//! back. A frame is drawn only if the answer to one of them is yes. That is a
//! few `stat` calls and two `try_recv`s twice a second while idle. See
//! `app::watch` for why polling beat inotify here.
//!
//! Everything is still synchronous: a slow search or a big graph build freezes
//! the UI while it runs, so anything expensive needs its own budget (see the
//! size caps in `text::search`, `map::graph`, and `text::highlight`) — and the
//! two that touch every file in the project use every core to do it.

mod app;
mod config;
mod files;
mod git;
mod licenses;
mod map;
mod parallel;
mod plugins;
mod terminal;
mod text;
mod ui;
mod update;

use std::path::PathBuf;
use std::time::Duration;

use anyhow::{Result, anyhow};
use crossterm::event::{
    self, DisableMouseCapture, EnableMouseCapture, Event, KeyEventKind, MouseEventKind,
};
use crossterm::execute;

use app::App;
use config::keys::Keyboard;
use config::{CONF_NAME, Config, PLUGINS_NAME};

/// `--help` output. Kept here as one literal rather than assembled from an
/// argument parser: there are only seven options, and a contributor changing
/// the CLI should be able to see the whole surface in one place.
const USAGE: &str = "\
tiny — a terminal knowledge manager

USAGE:
    tiny                open the current directory
    tiny <DIR>          open a folder; one that does not exist is created
    tiny <FILE>         edit one file, with its folder in the tree beside it;
                        a file that does not exist is created too

OPTIONS:
    -h, --help          show this message
    -V, --version       show the version
        --update        install the newest release, if there is one
        --config        print the path of the config file
        --licenses      terms of the bundled syntax definitions
        --uninstall     remove tiny; your notes are not touched

tiny writes nothing into a folder of yours that you did not name: no starter
page, no dotfiles, no per-project settings.

KEYS:
    ?                   every key and command, from inside the app
    /                   the bar: searches, or `*` first for a command
    Ctrl+G  Ctrl+L      source control, the project map
";

/// Print to stdout, and do not mind if nobody is listening.
///
/// `print!` panics when the pipe it is writing into closes, which is what
/// happens the moment someone quits the pager they piped `--licenses` into.
/// Every one of these outputs is a whole answer written in one go, so a reader
/// who stops early has read as much as they wanted and there is nothing to
/// report.
fn emit(text: &str) {
    let _ = std::io::Write::write_all(&mut std::io::stdout(), text.as_bytes());
}

/// Thin wrapper so the real work can use `?`.
///
/// Errors are printed with `{e:#}`, which walks anyhow's whole context chain —
/// so "cannot open /nope: No such file or directory" reaches the user instead
/// of just the innermost io error. Exit code 1 on failure, for scripts.
fn main() {
    if let Err(e) = real_main() {
        eprintln!("tiny: {e:#}");
        std::process::exit(1);
    }
}

/// Startup, in the order things have to happen.
///
/// The ordering here is not arbitrary — each step needs the one before it:
///
/// 1. Handle the options that never touch the disk (`--help`, `--version`,
///    `--config`) and return early.
/// 2. Load the config, which [`files::project::resolve`] needs for
///    `default_root` before it can decide what to do with the argument.
/// 3. Resolve the argument into a [`files::project::Target`], creating the
///    project if it does not exist.
/// 4. Write out the defaults on first run.
/// 5. Build the `App`, take over the terminal, loop, and restore.
///
/// There is one config file and it is read once, before anything else: which
/// folder ends up open cannot change how the program behaves. Only one warning
/// survives to the status bar, the more urgent first — a broken config file
/// beats "we just wrote you a config file".
fn real_main() -> Result<()> {
    let args: Vec<String> = std::env::args().skip(1).collect();
    match args.first().map(String::as_str) {
        Some("-h") | Some("--help") => {
            emit(USAGE);
            return Ok(());
        }
        Some("-V") | Some("--version") => {
            println!("tiny {}", update::running());
            return Ok(());
        }
        Some("--update") => return update::run_cli(),
        Some("--config") => {
            match Config::user_path() {
                Some(p) => println!("{}", p.display()),
                None => return Err(anyhow!("no config directory available")),
            }
            return Ok(());
        }
        Some("--licenses") => {
            emit(&licenses::notice());
            return Ok(());
        }
        Some("--uninstall") => return uninstall(),
        Some(a) if a.starts_with('-') => {
            return Err(anyhow!("unknown option `{a}` — try `tiny --help`"));
        }
        _ => {}
    }

    let (cfg, warn_config) = Config::load();
    let target = files::project::resolve(args.first().map(String::as_str), &cfg)?;

    // First run: write the defaults out so there is a file to edit. Done here
    // rather than in `load` so `--help` never touches the disk.
    let warn_first_run = match Config::user_path() {
        Some(p) if !p.exists() => match cfg.save() {
            Ok(p) => Some(format!("wrote {} to {}", CONF_NAME, p.display())),
            Err(e) => Some(format!("could not write {CONF_NAME}: {e}")),
        },
        _ => None,
    };

    let warning = warn_config.or(warn_first_run);
    let mut app = App::new(target, cfg, warning)?;
    // Which keys the terminal keeps for itself is known from the environment
    // alone, so it is settled before the first frame — see `Keyboard`.
    app.set_keyboard(Keyboard::detect());
    // The plugins, from the one real folder — the app is only ever told where
    // it is from here, so a test never loads anybody's plugins.
    app.plugins_dir = Config::plugins_dir();
    app.load_plugins();
    app.tell_plugins_what_is_open();
    // A release build asks, once, whether there is a newer one. A debug build
    // is somebody working on tiny, and is left alone — see `update`.
    if app.config.update_check && !cfg!(debug_assertions) {
        app.start_update_check(false);
    }

    // A clean message beats a panic when there is no terminal to draw on —
    // piping the binary or running it from a script hits this.
    let mut terminal = ratatui::try_init().map_err(|e| {
        anyhow!("no interactive terminal available ({e}); tiny needs a real terminal")
    })?;
    hand_back_the_terminal_on_panic();
    // Wheel events only reach a program that asks for them. Without this the
    // terminal translates a notch into three arrow keys of its own, which is
    // why scrolling used to jump. Best-effort: a terminal that will not report
    // the mouse is still perfectly usable from the keyboard.
    let mouse = execute!(std::io::stdout(), EnableMouseCapture).is_ok();
    let result = run(&mut terminal, &mut app);
    if mouse {
        let _ = execute!(std::io::stdout(), DisableMouseCapture);
    }
    ratatui::restore();
    result?;

    // A yes to the update question, carried out now that the terminal is an
    // ordinary terminal again: the installer's progress, and any question it
    // asks, need it.
    if let Some(version) = app.update_on_exit.take() {
        println!("updating tiny {} to {version}\n", update::running());
        let exe = update::install(&version)?;
        println!("\ntiny {version} installed — starting it");
        update::relaunch(&exe)?;
    }
    Ok(())
}

/// Turn off the mouse reporting tiny asked for, if it panics.
///
/// `ratatui::try_init` already leaves a hook that gives back raw mode and the
/// alternate screen. It cannot know about the request tiny makes on its own
/// account, so without this a panic drops you back at a shell whose terminal
/// is still reporting wheel events, with nothing on screen to say why.
///
/// It is safe to send when it was never turned on: the terminal is being told
/// to stop doing something it is not doing. That matters, because a hook runs
/// at a moment when what did and did not get set up is not knowable.
///
/// Ours runs first and ratatui's second, so the escape sequence goes out while
/// the alternate screen is still up and the panic message is the last thing
/// written.
fn hand_back_the_terminal_on_panic() {
    let next = std::panic::take_hook();
    std::panic::set_hook(Box::new(move |info| {
        let _ = execute!(std::io::stdout(), DisableMouseCapture);
        next(info);
    }));
}

/// How long the loop will wait for a key before going to look at the disk.
///
/// Half a second reads as "instantly" for a file changed by another program
/// while you are looking at it, and costs a stat of each open file and each
/// open directory twice a second — microseconds. Shorter would not be
/// noticeably quicker; much longer starts to feel like the screen is lying.
const IDLE: Duration = Duration::from_millis(500);

/// The event loop: draw, wait for something to happen, dispatch, repeat.
///
/// Note the order — the frame is drawn *before* the quit check, so the last
/// action a user takes is visible on screen before the program exits.
///
/// The inner loop is what keeps "one frame per thing that happened" true now
/// that waiting can end without an event. A timeout that finds nothing changed
/// on disk goes back to waiting rather than falling out and redrawing an
/// identical screen, so an idle tiny still draws nothing at all.
///
/// `ratatui::restore` in the caller runs whether or not this returns an error,
/// so a failure in here still gives the terminal back.
fn run(terminal: &mut ratatui::DefaultTerminal, app: &mut App) -> Result<()> {
    loop {
        terminal.draw(|f| ui::draw(f, app))?;
        if app.should_quit {
            return Ok(());
        }
        loop {
            if !event::poll(IDLE)? {
                // Nobody typed anything. Has anyone else been writing — has
                // the push we started come back — is there a newer tiny?
                // Each is asked every time: one with news must not keep the
                // others from being heard.
                let git = app.poll_git_job();
                let disk = app.rescan_disk();
                let update = app.poll_update();
                if git || disk || update {
                    break;
                }
                continue;
            }
            dispatch(app, event::read()?);
            break;
        }
        // Whatever else arrived while that was being handled — fast typing, a
        // paste — is taken now, before the one frame it will all appear in.
        // Each key is cheap on its own; what is not, a search of the whole
        // project, waits for `settle` and happens once for the lot.
        while !app.should_quit && event::poll(Duration::ZERO)? {
            dispatch(app, event::read()?);
        }
        app.settle();
    }
}

/// Hand one terminal event to the app.
fn dispatch(app: &mut App, event: Event) {
    match event {
        // Windows terminals report releases too; only presses, and the
        // repeats from holding a key down, should reach the app.
        Event::Key(k) if matches!(k.kind, KeyEventKind::Press | KeyEventKind::Repeat) => {
            app.handle_key(k)
        }
        // One notch, one line. Everything else the mouse reports — moves,
        // clicks, drags — is deliberately ignored: tiny is a keyboard program,
        // and the wheel is only here because three-line jumps make a page hard
        // to read.
        Event::Mouse(m) => match m.kind {
            MouseEventKind::ScrollDown => app.on_scroll(true, m.column),
            MouseEventKind::ScrollUp => app.on_scroll(false, m.column),
            _ => {}
        },
        // A resize, a paste, a key release: nothing to handle, but the screen
        // is redrawn for it exactly as it always was.
        _ => {}
    }
}

// ---- uninstall -------------------------------------------------------------

/// Everything an uninstall would delete.
///
/// Built in full before a single file is removed, so the prompt can show the
/// whole list and the user agrees to it as one thing. An uninstaller that
/// discovers what to delete as it goes is one you cannot say no to halfway.
///
/// Note what is *not* in here: anything under a project. tiny never wrote a
/// file into a folder of yours that you did not name, so there is nothing of
/// its own to take back. Deleting notes is not what removing a program means.
#[derive(Debug, Default, PartialEq, Eq)]
struct Removal {
    /// The running binary — whatever `tiny` you just typed.
    bin: Option<PathBuf>,
    /// `tiny.conf`, if one was ever written.
    conf: Option<PathBuf>,
    /// The plugins folder, only when there is nothing in it — the settings
    /// area's button makes it, and an empty one is nobody's work. One with
    /// plugins in it stays, and so does the folder around it.
    plugins_dir: Option<PathBuf>,
    /// The config directory, only when `tiny.conf` is the last thing in it,
    /// beside an empty plugins folder at most. A directory someone put their
    /// own files in stays.
    conf_dir: Option<PathBuf>,
    /// The `--root` cargo installed into, when its bookkeeping names tiny.
    /// `cargo uninstall` is then the right way to remove the binary, because
    /// it also forgets the entry — unlinking alone leaves cargo believing
    /// tiny is still installed.
    cargo_root: Option<PathBuf>,
}

impl Removal {
    /// Work out what to delete, given where the binary and the config live.
    ///
    /// Both are passed in rather than looked up so this is testable against a
    /// temporary directory instead of against the machine it runs on.
    fn plan(bin: Option<PathBuf>, conf: Option<PathBuf>) -> Self {
        let conf = conf.filter(|p| p.is_file());
        let is_empty = |d: &std::path::Path| {
            std::fs::read_dir(d)
                .map(|mut it| it.next().is_none())
                .unwrap_or(false)
        };
        let plugins_dir = conf
            .as_ref()
            .and_then(|p| p.parent())
            .map(|d| d.join(PLUGINS_NAME))
            .filter(|p| p.is_dir() && is_empty(p));
        let conf_dir = conf
            .as_ref()
            .and_then(|p| p.parent())
            // Nothing in it but what we are about to remove: the file, and an
            // empty plugins folder if there is one.
            .filter(|d| {
                std::fs::read_dir(d)
                    .map(|entries| {
                        entries.flatten().all(|e| {
                            e.file_name() == CONF_NAME
                                || (e.file_name() == PLUGINS_NAME && plugins_dir.is_some())
                        })
                    })
                    .unwrap_or(false)
            })
            .map(PathBuf::from);
        // `cargo install --root R` puts the binary in `R/bin` and its record
        // in `R/.crates.toml`, so the root is two levels up from the binary.
        let cargo_root = bin
            .as_ref()
            .filter(|p| p.is_file())
            .and_then(|p| p.parent()?.parent())
            .filter(|root| {
                std::fs::read_to_string(root.join(".crates.toml"))
                    .map(|s| s.contains("\"tiny "))
                    .unwrap_or(false)
            })
            .map(PathBuf::from);
        Self {
            bin: bin.filter(|p| p.is_file()),
            conf,
            plugins_dir,
            conf_dir,
            cargo_root,
        }
    }

    /// The list shown at the prompt, in the order things are removed.
    fn lines(&self) -> Vec<String> {
        let mut out = Vec::new();
        if let Some(p) = &self.conf {
            out.push(format!("  {}", p.display()));
        }
        if let Some(p) = &self.plugins_dir {
            out.push(format!("  {}/", p.display()));
        }
        if let Some(p) = &self.conf_dir {
            out.push(format!("  {}/", p.display()));
        }
        if let Some(p) = &self.bin {
            out.push(format!("  {}", p.display()));
        }
        out
    }

    /// Delete everything, collecting failures rather than stopping at the
    /// first. A config file that will not budge should not leave the binary
    /// behind as well — you would have to run the uninstaller again to finish,
    /// and it would have less to work with the second time.
    ///
    /// Config goes before the binary so that a failure part-way leaves `tiny`
    /// still runnable, and therefore still able to try again.
    fn perform(&self) -> Vec<String> {
        let mut errors = Vec::new();
        if let Some(p) = &self.conf
            && let Err(e) = std::fs::remove_file(p)
        {
            errors.push(format!("{}: {e}", p.display()));
        }
        if let Some(p) = &self.plugins_dir
            && let Err(e) = std::fs::remove_dir(p)
        {
            errors.push(format!("{}: {e}", p.display()));
        }
        if let Some(p) = &self.conf_dir
            && let Err(e) = std::fs::remove_dir(p)
        {
            errors.push(format!("{}: {e}", p.display()));
        }
        let Some(bin) = &self.bin else {
            return errors;
        };
        // Hand it to cargo when cargo owns it, so its bookkeeping is updated
        // too. Best effort: an old install whose cargo has since been removed
        // still gets unlinked below.
        if let Some(root) = &self.cargo_root {
            let done = std::process::Command::new("cargo")
                .args(["uninstall", "--quiet", "--root"])
                .arg(root)
                .arg("tiny")
                .status()
                .map(|s| s.success())
                .unwrap_or(false);
            if done {
                return errors;
            }
        }
        // Unix unlinks a running executable happily; Windows will not, so say
        // what to do about it rather than only that it did not work.
        if let Err(e) = std::fs::remove_file(bin) {
            let hint = if cfg!(target_os = "windows") {
                " — Windows will not delete a running program; close tiny and delete it"
            } else {
                ""
            };
            errors.push(format!("{}: {e}{hint}", bin.display()));
        }
        errors
    }
}

/// `tiny --uninstall`: show what will go, ask, then remove it.
///
/// The prompt reads from stdin rather than from the terminal directly, so
/// `echo y | tiny --uninstall` works for anyone scripting it and there is no
/// `--yes` flag to document. End-of-file counts as "no": a program removing
/// itself should need to be told, not merely left alone.
fn uninstall() -> Result<()> {
    let bin = std::env::current_exe().ok();
    let removal = Removal::plan(bin, Config::user_path());
    let lines = removal.lines();
    if lines.is_empty() {
        println!("nothing to remove — no tiny binary or config file found");
        return Ok(());
    }

    println!("This will remove:");
    for line in &lines {
        println!("{line}");
    }
    println!("\nYour notes and projects are not touched.");
    print!("\nRemove tiny? [y/N] ");
    let _ = std::io::Write::flush(&mut std::io::stdout());

    let mut reply = String::new();
    if std::io::BufRead::read_line(&mut std::io::stdin().lock(), &mut reply).is_err()
        || !matches!(reply.trim(), "y" | "Y" | "yes" | "Yes")
    {
        println!("canceled — nothing was removed");
        return Ok(());
    }

    let errors = removal.perform();
    if errors.is_empty() {
        println!("tiny is gone. Thanks for trying it.");
        return Ok(());
    }
    for e in &errors {
        eprintln!("tiny: could not remove {e}");
    }
    Err(anyhow!("{} item(s) could not be removed", errors.len()))
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;
    use std::path::Path;

    /// A fake install: `<root>/bin/tiny` plus cargo's record of it, and a
    /// config file in its own directory.
    fn fake_install(td: &Path) -> (PathBuf, PathBuf) {
        let bin_dir = td.join("root").join("bin");
        fs::create_dir_all(&bin_dir).unwrap();
        let bin = bin_dir.join("tiny");
        fs::write(&bin, "#!/bin/sh\n").unwrap();
        let conf_dir = td.join("config").join("tiny");
        fs::create_dir_all(&conf_dir).unwrap();
        let conf = conf_dir.join(CONF_NAME);
        fs::write(&conf, "borders = true\n").unwrap();
        (bin, conf)
    }

    #[test]
    fn uninstall_removes_the_binary_and_the_config_and_nothing_else() {
        let td = tempfile::tempdir().unwrap();
        let (bin, conf) = fake_install(td.path());
        // A note living beside the install, to prove it survives.
        let note = td.path().join("notes.md");
        fs::write(&note, "mine").unwrap();

        let removal = Removal::plan(Some(bin.clone()), Some(conf.clone()));
        assert!(removal.perform().is_empty(), "clean removal");

        assert!(!bin.exists(), "the binary is gone");
        assert!(!conf.exists(), "the config is gone");
        assert!(
            !conf.parent().unwrap().exists(),
            "its directory went with it"
        );
        assert!(note.exists(), "a note beside it is untouched");
    }

    #[test]
    fn a_config_directory_holding_someone_elses_files_is_left_alone() {
        let td = tempfile::tempdir().unwrap();
        let (_, conf) = fake_install(td.path());
        let theirs = conf.parent().unwrap().join("notes-to-self.txt");
        fs::write(&theirs, "keep me").unwrap();

        let removal = Removal::plan(None, Some(conf.clone()));
        assert_eq!(
            removal.conf_dir, None,
            "the directory is not ours to delete"
        );
        removal.perform();
        assert!(!conf.exists(), "our file still goes");
        assert!(theirs.exists(), "theirs stays");
    }

    #[test]
    fn an_empty_plugins_folder_goes_with_the_config() {
        let td = tempfile::tempdir().unwrap();
        let (_, conf) = fake_install(td.path());
        let plugins = conf.parent().unwrap().join(PLUGINS_NAME);
        fs::create_dir(&plugins).unwrap();

        let removal = Removal::plan(None, Some(conf.clone()));
        assert_eq!(removal.plugins_dir.as_ref(), Some(&plugins));
        assert!(removal.perform().is_empty());
        assert!(!conf.parent().unwrap().exists(), "the whole folder went");
    }

    #[test]
    fn installed_plugins_are_kept_and_so_is_their_folder() {
        let td = tempfile::tempdir().unwrap();
        let (_, conf) = fake_install(td.path());
        let plugins = conf.parent().unwrap().join(PLUGINS_NAME);
        fs::create_dir(&plugins).unwrap();
        fs::write(plugins.join("words.lua"), "-- mine").unwrap();

        let removal = Removal::plan(None, Some(conf.clone()));
        assert_eq!(removal.plugins_dir, None, "somebody's plugins");
        assert_eq!(removal.conf_dir, None, "and the folder they are in");
        removal.perform();
        assert!(!conf.exists(), "the config still goes");
        assert!(plugins.join("words.lua").exists(), "the plugin stays");
    }

    #[test]
    fn a_cargo_install_is_recognized_by_its_bookkeeping() {
        let td = tempfile::tempdir().unwrap();
        let (bin, _) = fake_install(td.path());
        let root = td.path().join("root");

        assert_eq!(
            Removal::plan(Some(bin.clone()), None).cargo_root,
            None,
            "no record means no cargo"
        );

        fs::write(
            root.join(".crates.toml"),
            "[v1]\n\"tiny 0.1.2 (path+file:///src)\" = [\"tiny\"]\n",
        )
        .unwrap();
        assert_eq!(
            Removal::plan(Some(bin), None).cargo_root,
            Some(root),
            "a record naming tiny means cargo should do the removing"
        );
    }

    #[test]
    fn planning_against_nothing_finds_nothing_to_remove() {
        let td = tempfile::tempdir().unwrap();
        let removal = Removal::plan(Some(td.path().join("nope")), Some(td.path().join("gone")));
        assert_eq!(removal, Removal::default());
        assert!(removal.lines().is_empty(), "the prompt would be empty");
    }
}

