//! What links to what, and the screen that shows it.
//!
//! Two layers, deliberately apart:
//!
//! - [`graph`] — the facts. Which files exist, and which of them reach which
//!   others, by wikilink, by markdown link, or by calling a function defined
//!   somewhere else. Built by scanning the project; knows nothing about
//!   drawing.
//! - [`view`] — the thing you look at. Takes a [`graph::Graph`], decides
//!   what is on screen, where each box sits, and what the cursor is on.
//!
//! The split is what keeps the layout testable: [`view`] can be asked where
//! it put a box without a terminal existing. Actually painting the boxes and
//! the lines between them is `ui::map`'s job, one layer further out
//! again.

#[cfg(test)]
pub(crate) mod testing;

pub mod graph;
pub mod layout;
pub mod scan;
pub mod view;

files.src/map/scan.rs:
//! Reading one file and saying what is in it.
//!
//! Everything [`super::graph::build`] needs to know about a single file, and
//! nothing about the graph it ends up in. Split out because these are two
//! different kinds of work: this half is parsers and heuristics and has to
//! know about Python's import syntax; the other half is bookkeeping over the
//! answers.
//!
//! # The budget
//!
//! Building the graph reads every file it can find something in, while the
//! user waits — see the event loop's docs in `main`. So every read here is
//! capped at [`MAX_PARSE_BYTES`], and a file over the line is skipped rather
//! than truncated: half a parse produces confidently wrong symbols, where no
//! parse produces none. A file with nothing to find — a picture, a binary, a
//! language with no grammar here — is never opened at all; see [`facts_of`].
//!
//! # Test code is not the project
//!
//! [`strip_tests`] takes a module's tests out before its calls are collected.
//! A test file calls everything, so leaving them in makes every file look
//! connected to every other, and the map's whole value is in the connections
//! that are not there.

use std::collections::{BTreeMap, BTreeSet, HashMap};
use std::io::Read;
use std::path::{Path, PathBuf};
use std::sync::LazyLock;

use tree_sitter_tags::{TagsConfiguration, TagsContext};

use crate::map::graph::{EdgeKind, NodeKind};

/// Source files past this size are not parsed for symbols.
pub(super) const MAX_PARSE_BYTES: u64 = 1024 * 1024;

// ---- language support -----------------------------------------------------

/// Tags configurations are expensive to compile, so each is built once.
/// A grammar that fails to compile its query is simply skipped — one bad
/// language should not take the whole graph down with it.
static PYTHON: LazyLock<Option<TagsConfiguration>> = LazyLock::new(|| {
    TagsConfiguration::new(
        tree_sitter_python::LANGUAGE.into(),
        tree_sitter_python::TAGS_QUERY,
        "",
    )
    .ok()
});
static RUST: LazyLock<Option<TagsConfiguration>> = LazyLock::new(|| {
    TagsConfiguration::new(
        tree_sitter_rust::LANGUAGE.into(),
        tree_sitter_rust::TAGS_QUERY,
        "",
    )
    .ok()
});
static JAVASCRIPT: LazyLock<Option<TagsConfiguration>> = LazyLock::new(|| {
    TagsConfiguration::new(
        tree_sitter_javascript::LANGUAGE.into(),
        tree_sitter_javascript::TAGS_QUERY,
        tree_sitter_javascript::LOCALS_QUERY,
    )
    .ok()
});

/// Languages with a tree-sitter grammar compiled in. Adding one means adding
/// a variant here and wiring it through [`lang_of`] and [`tags_for`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum Lang {
    Python,
    Rust,
    JavaScript,
}

/// Map a file extension to a parseable language, or `None` for everything
/// else. TypeScript is absent deliberately — it needs its own grammar, and
/// falling back to the JavaScript one mis-parses type annotations.
pub(crate) fn lang_of(path: &Path) -> Option<Lang> {
    match path
        .extension()
        .and_then(|e| e.to_str())
        .map(str::to_ascii_lowercase)
        .as_deref()
    {
        Some("py" | "pyi") => Some(Lang::Python),
        Some("rs") => Some(Lang::Rust),
        Some("js" | "jsx" | "mjs" | "cjs") => Some(Lang::JavaScript),
        _ => None,
    }
}

/// The compiled tags query for a language, or `None` if its query failed to
/// compile at first use.
pub(super) fn tags_for(lang: Lang) -> Option<&'static TagsConfiguration> {
    match lang {
        Lang::Python => PYTHON.as_ref(),
        Lang::Rust => RUST.as_ref(),
        Lang::JavaScript => JAVASCRIPT.as_ref(),
    }
}

// ---- one file's contribution ----------------------------------------------

/// What one file contributes to the graph, before anything is resolved.
///
/// Kept separate from [`super::graph::Node`] because it is scratch: the resolution pass
/// consumes it and only `defines` survives onto the node, for the tooltip.
#[derive(Debug, Default)]
pub(super) struct Facts {
    /// Symbols defined here.
    pub(super) defines: BTreeSet<String>,
    /// Symbols called here, with how many times.
    pub(super) calls: BTreeMap<String, usize>,
    /// Wikilink and markdown-link targets, as written.
    pub(super) links: Vec<(String, EdgeKind)>,
}

/// Classify a file. Order matters: markdown is checked before the prose list
/// because it is usually *in* that list but has a link syntax of its own.
pub(super) fn node_kind(path: &Path, prose_exts: &[String]) -> NodeKind {
    match path
        .extension()
        .and_then(|e| e.to_str())
        .map(str::to_ascii_lowercase)
    {
        Some(e) if matches!(e.as_str(), "md" | "markdown" | "mdown" | "mkd") => NodeKind::Note,
        Some(e) if prose_exts.iter().any(|p| p.eq_ignore_ascii_case(&e)) => NodeKind::Prose,
        Some(_) if lang_of(path).is_some() => NodeKind::Code,
        // Source in a language tiny cannot parse still shows, it just has no
        // outgoing call edges.
        Some(e) if is_sourcelike(&e) => NodeKind::Code,
        _ => NodeKind::Other,
    }
}

/// Extensions that are recognizably source without a grammar to parse them.
/// These become [`NodeKind::Code`] nodes with no outgoing call edges, so a Go
/// or C++ project still draws as something rather than as a pile of orphans.
pub(super) fn is_sourcelike(ext: &str) -> bool {
    matches!(
        ext,
        "c" | "h"
            | "cpp"
            | "hpp"
            | "cc"
            | "go"
            | "java"
            | "rb"
            | "php"
            | "sh"
            | "bash"
            | "fish"
            | "ts"
            | "tsx"
            | "lua"
            | "zig"
            | "swift"
            | "kt"
            | "cs"
    )
}

/// What one file contributes, read only when there is something to find in
/// it: links in prose, definitions and calls in a language with a grammar.
/// Everything else is a node and nothing more, so it is never opened —
/// reading every picture in a folder to throw it away was most of what a
/// media-heavy project cost the map.
pub(super) fn facts_of(ctx: &mut TagsContext, path: &Path, kind: NodeKind) -> Facts {
    let mut f = Facts::default();
    match kind {
        NodeKind::Note | NodeKind::Prose => {
            if let Some(text) = read_text(path) {
                collect_links(&text, kind, &mut f);
            }
        }
        NodeKind::Code => {
            if let Some(lang) = lang_of(path)
                && !is_test_file(path)
                && let Some(text) = read_text(path)
            {
                let body = strip_tests(lang, &text);
                collect_symbols(ctx, lang, body, &mut f);
                if lang == Lang::Rust {
                    collect_path_calls(body, &mut f);
                }
            }
        }
        NodeKind::Other => {}
    }
    f
}

/// Read a file if it is small enough and looks like text. Deliberately a
/// local copy of `search::read_text` rather than a shared helper: the two have
/// different size limits, and the graph swallows errors as `None` where search
/// wants a `Result`.
///
/// One open, and the size taken from it rather than from a second lookup by
/// path. The read stops one byte past the limit, so a file that grew after it
/// was measured is still refused rather than read whole.
pub(crate) fn read_text(path: &Path) -> Option<String> {
    let file = std::fs::File::open(path).ok()?;
    let len = file.metadata().ok()?.len();
    if len > MAX_PARSE_BYTES {
        return None;
    }
    let mut bytes = Vec::with_capacity(len as usize);
    file.take(MAX_PARSE_BYTES + 1)
        .read_to_end(&mut bytes)
        .ok()?;
    if bytes.len() as u64 > MAX_PARSE_BYTES || bytes.contains(&0) {
        return None;
    }
    String::from_utf8(bytes).ok()
}

/// Wikilinks, plus relative markdown links to files inside the project.
pub(super) fn collect_links(text: &str, kind: NodeKind, f: &mut Facts) {
    for target in crate::text::markdown::wikilinks(text) {
        f.links.push((target, EdgeKind::Wikilink));
    }
    if kind != NodeKind::Note {
        return; // `[a](b)` only means a link in markdown
    }
    let bytes = text.as_bytes();
    let mut i = 0;
    while i + 1 < bytes.len() {
        // `](` is the seam of an inline link; find its closing paren.
        if bytes[i] == b']'
            && bytes[i + 1] == b'('
            && let Some(end) = text[i + 2..].find(')')
        {
            {
                let dest = text[i + 2..i + 2 + end].trim();
                // Titles and anchors are not part of the path.
                let dest = dest.split_whitespace().next().unwrap_or(dest);
                let dest = dest.split('#').next().unwrap_or(dest);
                if !dest.is_empty() && !dest.contains("://") && !dest.starts_with("mailto:") {
                    f.links.push((dest.to_string(), EdgeKind::Link));
                }
                i += 2 + end;
                continue;
            }
        }
        i += 1;
    }
}

/// Whether a file exists to test other files. Its helpers are not part of how
/// the project fits together, and they collide with real names constantly.
///
/// Covers the common conventions across languages: a `test_` prefix (Python),
/// `_test.` (Go, Rust), `.test.` and `.spec.` (JavaScript), and any path
/// component named `tests` or `__tests__`.
pub(super) fn is_test_file(path: &Path) -> bool {
    let name = path
        .file_name()
        .map(|n| n.to_string_lossy().to_ascii_lowercase())
        .unwrap_or_default();
    name.starts_with("test_")
        || name.contains("_test.")
        || name.contains(".test.")
        || name.contains(".spec.")
        || path
            .components()
            .any(|c| matches!(c.as_os_str().to_str(), Some("tests" | "__tests__")))
}

/// Drop a trailing test module. Rust puts its tests in the same file behind
/// `#[cfg(test)]`, and those helpers — `fixture`, `render`, `plain` — shadow
/// real names across the whole project if they are counted.
pub(super) fn strip_tests(lang: Lang, text: &str) -> &str {
    match lang {
        Lang::Rust => match text.find("\n#[cfg(test)]") {
            Some(at) => &text[..=at],
            None => text,
        },
        _ => text,
    }
}

/// Definitions and calls, via the language's tags query.
///
/// tree-sitter's tags queries emit a stream of tagged ranges with a syntax
/// type name — `function`, `call`, `reference.implementation`, and so on. Two
/// filters narrow that to something useful:
///
/// - **Definitions** are kept only for callable things. `mod x;` and `X = 1`
///   are definitions too, but nothing calls them, and counting them makes
///   every `mod` line look like a function.
/// - **References** are kept only when typed `call`. The others describe type
///   relationships, not one file reaching into another.
///
/// Parse failures return quietly: a file with a syntax error contributes
/// nothing rather than taking the graph down.
pub(super) fn collect_symbols(ctx: &mut TagsContext, lang: Lang, text: &str, f: &mut Facts) {
    let Some(config) = tags_for(lang) else { return };
    let Ok((tags, _)) = ctx.generate_tags(config, text.as_bytes(), None) else {
        return;
    };
    for tag in tags.flatten() {
        let Some(name) = text.get(tag.name_range.clone()) else {
            continue;
        };
        if name.is_empty() {
            continue;
        }
        let syntax = config.syntax_type_name(tag.syntax_type_id);
        if tag.is_definition {
            if is_callable(syntax) {
                f.defines.insert(name.to_string());
            }
        } else {
            // Only calls are followed. `reference.implementation` and friends
            // describe type relationships, not one file reaching into another.
            if syntax == "call" {
                *f.calls.entry(name.to_string()).or_insert(0) += 1;
            }
        }
    }
}

/// Whether a definition is of something you can call or build — what the
/// map links calls to, and what `goto function` goes to.
///
/// `mod x;` and `X = 1` are definitions too, but nothing calls them, and
/// counting them makes every `mod` line look like a function.
fn is_callable(syntax: &str) -> bool {
    matches!(
        syntax,
        "function" | "method" | "class" | "interface" | "macro" | "struct" | "enum"
    )
}

/// Every callable thing defined in `text`, as its name, line and character
/// column — where `goto function` lands.
///
/// The same definitions [`collect_symbols`] counts for the map, so the two
/// agree on what a function is. Test code is included here: jumping to a test
/// is a perfectly good thing to want, where linking to one was not.
pub(crate) fn definitions(
    ctx: &mut TagsContext,
    lang: Lang,
    text: &str,
) -> Vec<(String, usize, usize)> {
    let Some(config) = tags_for(lang) else {
        return Vec::new();
    };
    let Ok((tags, _)) = ctx.generate_tags(config, text.as_bytes(), None) else {
        return Vec::new();
    };
    tags.flatten()
        .filter(|t| t.is_definition && is_callable(config.syntax_type_name(t.syntax_type_id)))
        .filter_map(|t| {
            let name = text.get(t.name_range.clone())?;
            // `span` is the name's own position; its column is in bytes.
            let line_start = t.name_range.start.checked_sub(t.span.start.column)?;
            let col = text.get(line_start..t.name_range.start)?.chars().count();
            Some((name.to_string(), t.span.start.row, col))
        })
        .collect()
}

/// Rust calls written through a path — `helpers::compute()`, `Config::load()`.
///
/// A gap in the shipped Rust tags query, and not a small one: it tags a bare
/// `compute()` as a call and says nothing about `helpers::compute()`, which is
/// how a Rust file nearly always reaches into another one. Without this, the
/// map of a Rust project is almost empty.
///
/// Text scanning rather than a second tree-sitter query, for the same reason
/// the language list is short: this is thirty lines against a whole query to
/// compile and keep in step with the grammar. The cost is that a call written
/// inside a comment or a string counts. It is bounded by what happens next —
/// a name only becomes an edge if some file in the project defines it, and
/// `max_ambiguity` throws out the names too common to mean anything.
pub(super) fn collect_path_calls(text: &str, f: &mut Facts) {
    let bytes = text.as_bytes();
    let is_word = |b: u8| b.is_ascii_alphanumeric() || b == b'_';
    let mut i = 0;
    while let Some(at) = text[i..].find("::") {
        let start = i + at + 2;
        let mut end = start;
        while end < bytes.len() && is_word(bytes[end]) {
            end += 1;
        }
        i = start.max(i + at + 1);
        if end == start {
            continue; // `::<T>`, `::*`, or a stray pair of colons
        }
        // Only a call, not a `use` path or a type: the parenthesis is what
        // says something is being invoked. Turbofish sits between the two.
        let mut after = end;
        if bytes.get(after) == Some(&b':') && bytes.get(after + 1) == Some(&b':') {
            continue; // a longer path; the last segment is the call
        }
        while bytes.get(after) == Some(&b' ') {
            after += 1;
        }
        if bytes.get(after) == Some(&b'(') {
            *f.calls.entry(text[start..end].to_string()).or_insert(0) += 1;
        }
        i = end;
    }
}

/// Turn a written target into a file. Tries, in order: the path as given
/// relative to the linking file, the same relative to the root, and finally
/// the bare stem — which is how `[[design]]` finds `notes/design.md`.
///
/// The order is the whole design. Relative-to-the-linking-file comes first so
/// `../utils` means the neighbor you meant, not something with the same name
/// on the other side of the project. The bare-stem fallback comes last and is
/// accepted *only when exactly one file answers to the name*, so an ambiguous
/// `[[index]]` in a project with five `index.js` files draws no edge rather
/// than a wrong one.
///
/// An extensionless target is tried against a list of likely suffixes, and
/// against directory-index filenames (`mod.rs`, `__init__.py`, `index.js`), so
/// `import utils` finds `utils/__init__.py`.
///
/// Returns `None` for anything it cannot place — a link to a file that does
/// not exist simply produces no edge, silently, which is correct for a graph
/// but does mean a typo'd wikilink is invisible here.
pub(super) fn resolve_link(
    target: &str,
    root: &Path,
    from_dir: Option<&Path>,
    by_rel: &HashMap<String, usize>,
    by_stem: &HashMap<String, Vec<usize>>,
) -> Option<usize> {
    let target = target.trim().trim_start_matches("./");
    if target.is_empty() {
        return None;
    }

    // Candidate suffixes for extensionless targets.
    let mut candidates: Vec<String> = vec![target.to_string()];
    if Path::new(target).extension().is_none() {
        for ext in ["md", "markdown", "txt", "rs", "py", "js", "ts"] {
            candidates.push(format!("{target}.{ext}"));
        }
        for tail in ["mod.rs", "__init__.py", "index.js"] {
            candidates.push(format!("{target}/{tail}"));
        }
    }

    for cand in &candidates {
        // Relative to the linking file first: `../utils` should mean the
        // neighbor, not something with the same name elsewhere.
        if let Some(dir) = from_dir {
            let joined = normalize(&dir.join(cand));
            if let Ok(rel) = joined.strip_prefix(root) {
                let key = rel.to_string_lossy().replace('\\', "/");
                if let Some(&id) = by_rel.get(&key) {
                    return Some(id);
                }
            }
        }
        if let Some(&id) = by_rel.get(cand.as_str()) {
            return Some(id);
        }
    }

    // Last resort: a bare name, matched against file stems. Only accepted
    // when exactly one file answers to it.
    let stem = Path::new(target)
        .file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or(target)
        .to_ascii_lowercase();
    match by_stem.get(&stem) {
        Some(ids) if ids.len() == 1 => Some(ids[0]),
        _ => None,
    }
}

/// Resolve `.` and `..` without touching the filesystem.
///
/// Purely lexical, unlike `canonicalize`: link targets routinely name files
/// that do not exist, and a syscall per candidate per link would be slow. Note
/// that `pop` on an empty buffer is a no-op, so `../..` from the root cannot
/// escape upwards — it just flattens.
pub(super) fn normalize(path: &Path) -> PathBuf {
    let mut out = PathBuf::new();
    for c in path.components() {
        match c {
            std::path::Component::ParentDir => {
                out.pop();
            }
            std::path::Component::CurDir => {}
            other => out.push(other.as_os_str()),
        }
    }
    out
}

files.src/map/testing.rs:
//! Fixtures shared by the map's own tests.
//!
//! [`view`](super::view) and [`layout`](super::layout) are two halves of one
//! `ProjectMap`, so their tests want the same small project to look at: two
//! notes that link to each other, two source files that call across, and one
//! file nothing reaches. Building it in one place keeps the two halves
//! agreeing about what they are describing.

use std::path::Path;

use crossterm::event::{KeyCode, KeyEvent};

use crate::config::keys::Action;
use crate::map::graph;
use crate::map::view::ProjectMap;

use crossterm::event::{KeyEventKind, KeyModifiers};
use std::fs;

pub(crate) fn write(dir: &Path, rel: &str, body: &str) {
    let p = dir.join(rel);
    fs::create_dir_all(p.parent().unwrap()).unwrap();
    fs::write(p, body).unwrap();
}

/// Two notes that link to each other, two code files that call across,
/// and one file connected to nothing.
pub(crate) fn fixture() -> (tempfile::TempDir, ProjectMap) {
    let td = tempfile::tempdir().unwrap();
    write(td.path(), "notes/design.md", "see [[architecture]]\n");
    write(td.path(), "notes/architecture.md", "back to [[design]]\n");
    write(td.path(), "src/utils.py", "def load():\n    return 1\n");
    write(td.path(), "src/main.py", "import utils\nutils.load()\n");
    write(td.path(), "notes/alone.md", "nothing points here\n");
    let view = ProjectMap::build(td.path(), &graph::Options::default());
    (td, view)
}

pub(crate) fn k(code: KeyCode) -> KeyEvent {
    KeyEvent {
        code,
        modifiers: KeyModifiers::NONE,
        kind: KeyEventKind::Press,
        state: crossterm::event::KeyEventState::NONE,
    }
}

pub(crate) fn ch(c: char) -> KeyEvent {
    k(KeyCode::Char(c))
}

/// What the shipped keyboard makes of a key. These tests are about the
/// view, not the bindings.
pub(crate) fn act(key: KeyEvent) -> Option<Action> {
    crate::config::keys::Keymap::default().find(crate::config::keys::Context::Map, &key)
}

pub(crate) fn rel_of(view: &ProjectMap, i: usize) -> &str {
    &view.graph.nodes[i].rel
}

pub(crate) fn visible_names(view: &ProjectMap) -> Vec<&str> {
    view.visible_indices()
        .into_iter()
        .map(|i| rel_of(view, i))
        .collect()
}

files.src/map/view.rs:
//! The project map: what is on it, and what the keyboard does to it.
//!
//! Every file in the project is a box with its name in it, and the connections
//! between them are lines, the way anyone would draw this on paper. This half
//! owns the *state* — which file is selected, which connection kinds are
//! switched on, what the filter is hiding. Where each box physically sits is
//! [`super::layout`]'s job, and painting it is `ui::map`'s.
//!
//! Folders are not boxes. They are not selectable, nothing connects to one,
//! and opening one does nothing — a folder is *where files are*, and the
//! heading is how the picture says so.
//!
//! Navigation is spatial: the arrow keys move to the nearest file in that
//! direction, so the graph is something you walk around rather than a list
//! that happens to be drawn as dots.
//!
//! # Division of labor
//!
//! [`super::graph`] decides *what connects to what*; this module decides
//! *what you can see and do*; [`super::layout`] decides *where it sits*. The
//! `Graph` itself is never mutated after construction — filtering happens by
//! asking [`ProjectMap::node_visible`] and [`ProjectMap::edge_visible`] at
//! draw time, so toggling an edge kind is instant and reversible.
//!
//! # Every frame is per file, never per file per edge
//!
//! A frame asks, for every file, whether anything reaches it, and draws the
//! selected file's lines. Scanning the whole edge list to answer either is
//! quadratic, and on a vault of twenty thousand notes that was two seconds a
//! keypress. So the answers are indexed once, at build time: `touching` lists
//! each file's edges, and `shown` holds the filter's verdict on each file
//! until the filter changes.
//!
//! # Coordinates
//!
//! `pos` is written by [`super::layout`] in **grid** units — one per box, not
//! one per character — with **y running upwards**, which is why `Up` calls
//! `move_towards(0.0, 1.0)`. Navigation then walks the picture exactly as it
//! is drawn.

use std::collections::HashSet;
use std::path::{Path, PathBuf};

use crate::config::keys::Action;
use crate::map::graph::{self, Edge, EdgeKind, Graph, Node};
use crate::map::layout::{self, Link};

/// What a keypress asked the app to do. Named for the request rather than
/// the key, since `keys::Action` is now what a key resolves to.
///
/// The view handles its own navigation but cannot open files or close itself —
/// both need `App`. Returning an intent keeps this module free of any
/// dependency on application state.
pub enum Intent {
    /// Handled internally; nothing for `App` to do.
    None,
    /// Leave the map and go back to the tree.
    Close,
    /// Open this file in the editor, closing the map.
    Open(PathBuf),
    /// Read the project again and draw a fresh map of it. The layout is
    /// deterministic, so redrawing the same files is a no-op — what this is
    /// for is picking up files and links that changed on disk.
    Rebuild,
}

/// The link graph plus everything about how it is currently being looked at.
pub struct ProjectMap {
    /// Built once and never modified. All filtering is applied at read time.
    pub graph: Graph,
    /// The project folder the map is of. Nothing above it is ever walked, so
    /// this is the whole extent of the picture.
    pub(super) root: PathBuf,
    /// Laid-out position of each node, parallel to `graph.nodes`.
    pub pos: Vec<(f64, f64)>,
    /// Index of the node under the cursor. May point at something currently
    /// filtered out, which is why [`ProjectMap::selected_node`] checks
    /// visibility and [`ProjectMap::ensure_selection`] repairs it.
    pub selected: usize,
    /// Which edge kinds to draw: wikilink, link, call. Indexed by
    /// [`kind_index`], and bound to the `1`-`3` keys.
    pub kinds: [bool; 3],
    /// Substring matched against each node's relative path, case-insensitively.
    /// Empty means no filtering. Changed only through
    /// [`ProjectMap::set_filter`], which keeps `shown` in step with it.
    filter: String,
    /// Whether each node passes the filter, parallel to `graph.nodes`.
    shown: Vec<bool>,
    /// The edges touching each node, as indices into `graph.edges` in edge
    /// order. What a file connects to costs that file's edges to find, not
    /// the whole graph's.
    touching: Vec<Vec<usize>>,
    /// Each file's name as drawn in its box — see [`layout::label_of`].
    pub(super) labels: Vec<String>,
    /// The folder each file sits in, as an index into `folders`.
    pub(super) folder: Vec<usize>,
    /// Every folder holding a file, in path order, without a trailing slash.
    /// The project root is `""`, so it comes first.
    pub(super) folders: Vec<String>,
}

/// Position of an edge kind in [`ProjectMap::kinds`], and in the `1`-`3` key
/// bindings. `pub` because `ui` needs it to draw the toggle row.
pub fn kind_index(kind: EdgeKind) -> usize {
    match kind {
        EdgeKind::Wikilink => 0,
        EdgeKind::Link => 1,
        EdgeKind::Call => 2,
    }
}

impl ProjectMap {
    /// Build the graph and put the cursor somewhere sensible. Laying it out
    /// is `place`'s job, and happens per frame against the pane it has.
    ///
    /// Everything expensive happens here, synchronously — this is what
    /// opening the map costs.
    pub fn build(root: &Path, opts: &graph::Options) -> Self {
        let graph = graph::build(root, opts);
        let mut touching = vec![Vec::new(); graph.nodes.len()];
        for (n, e) in graph.edges.iter().enumerate() {
            touching[e.from].push(n);
            touching[e.to].push(n);
        }
        let labels = graph
            .nodes
            .iter()
            .map(|n| layout::label_of(&n.name))
            .collect();
        let (folder, folders) = layout::folders_of(&graph.nodes);
        let mut view = Self {
            pos: vec![(0.0, 0.0); graph.nodes.len()],
            shown: vec![true; graph.nodes.len()],
            graph,
            root: root.to_path_buf(),
            selected: 0,
            kinds: [true; 3],
            filter: String::new(),
            touching,
            labels,
            folder,
            folders,
        };
        view.select_busiest();
        // `pos` is written by `place`, which only runs when a frame is drawn.
        // Seed it against a nominal pane so the arrow keys mean something if a
        // key ever arrives before the first draw; the first frame overwrites
        // this with the real geometry.
        view.place(100, 30);
        view
    }

    // ---- what is on screen ------------------------------------------------

    /// Whether a file is drawn at all.
    ///
    /// Only the bar's filter can hide one. A file that links to nothing is still
    /// part of the project — it is filed under its own heading rather than
    /// left out, because a map that quietly omits things is a map you cannot
    /// trust to tell you what is there. See [`ProjectMap::connected`].
    pub fn node_visible(&self, i: usize) -> bool {
        self.shown.get(i).copied().unwrap_or(false)
    }

    /// What the map is narrowed to, as typed. Empty when it is not.
    pub fn filter(&self) -> &str {
        &self.filter
    }

    /// A file's name as it is written in its box.
    pub fn label(&self, i: usize) -> &str {
        &self.labels[i]
    }

    /// Whether any connection reaches this file, in either direction.
    ///
    /// Depends on which edge kinds are switched on, which is the point: turn
    /// `call` off in a code project and most files move to the unconnected
    /// heading, because with calls hidden nothing does connect them.
    ///
    /// Deliberately blind to the filter. A filter narrows what you are
    /// looking at; it does not change what a file is joined to, and filing
    /// every file as unconnected the moment you type into the box would be
    /// telling you something untrue about your project.
    pub(super) fn connected(&self, i: usize) -> bool {
        self.touching[i]
            .iter()
            .any(|&e| self.kind_on(&self.graph.edges[e]))
    }

    /// Whether this edge's kind is switched on, ignoring everything else.
    pub(super) fn kind_on(&self, e: &Edge) -> bool {
        self.kinds[kind_index(e.kind)]
    }

    /// An edge is drawn only when its kind is on *and* both endpoints are
    /// visible — otherwise a filter would leave lines dangling into nothing.
    pub fn edge_visible(&self, e: &Edge) -> bool {
        self.kind_on(e) && self.node_visible(e.from) && self.node_visible(e.to)
    }

    /// Every drawn node, in index order. Also the order `Tab` steps through.
    pub fn visible_indices(&self) -> Vec<usize> {
        (0..self.graph.nodes.len())
            .filter(|i| self.shown[*i])
            .collect()
    }

    /// The node under the cursor, or `None` when the cursor is on something
    /// currently filtered out.
    pub fn selected_node(&self) -> Option<&Node> {
        let i = self.selected;
        self.node_visible(i).then(|| self.graph.nodes.get(i))?
    }

    /// The drawn edges touching a file, in edge order.
    fn edges_of(&self, i: usize) -> impl Iterator<Item = &Edge> {
        self.touching
            .get(i)
            .into_iter()
            .flatten()
            .map(|&e| &self.graph.edges[e])
            .filter(|e| self.edge_visible(e))
    }

    /// Edges touching a node, split into the ones it points at and the ones
    /// that point at it.
    pub fn connections(&self, i: usize) -> (Vec<&Edge>, Vec<&Edge>) {
        self.edges_of(i).partition(|e| e.from == i)
    }

    /// The files drawn joined to this one, each once however many edges run
    /// between them — the far ends of the lines the map draws for it.
    pub fn neighbors(&self, i: usize) -> Vec<usize> {
        let mut seen = HashSet::new();
        self.edges_of(i)
            .map(|e| if e.from == i { e.to } else { e.from })
            .filter(|other| seen.insert(*other))
            .collect()
    }

    /// Every drawn connection, with all the edges between a pair of files
    /// merged into one.
    ///
    /// Two files that share a dozen function names are one connection, not a
    /// dozen parallel lines. The lines were the tangle: the graph is keyed per
    /// symbol so that the detail strip can name them, but the picture only has
    /// to say *that* they are connected.
    pub fn links(&self) -> Vec<Link> {
        let mut seen = HashSet::new();
        self.graph
            .edges
            .iter()
            .filter(|e| self.edge_visible(e))
            .map(|e| Link {
                a: e.from.min(e.to),
                b: e.from.max(e.to),
            })
            .filter(|l| seen.insert((l.a, l.b)))
            .collect()
    }

    // ---- layout -----------------------------------------------------------

    /// Park the cursor on the first drawn node, used at build time and
    /// whenever a filter change strands it.
    fn select_first_visible(&mut self) {
        if let Some(i) = self.shown.iter().position(|s| *s) {
            self.selected = i;
        }
    }

    /// Put the cursor on the file with the most connections.
    ///
    /// Only used when the map is first opened, and only because the map draws
    /// the cursor's connections rather than everyone's: landing on whichever
    /// file happens to sort first would often mean opening on a picture with
    /// no lines in it. The busiest file is the one that says the most about
    /// how a project fits together, so it is the right thing to be looking at
    /// before you have asked for anything in particular.
    fn select_busiest(&mut self) {
        let degree = |i: usize| {
            self.touching[i]
                .iter()
                .filter(|&&e| self.kind_on(&self.graph.edges[e]))
                .count()
        };
        if let Some(i) = self
            .visible_indices()
            .into_iter()
            .max_by_key(|i| degree(*i))
        {
            self.selected = i;
        }
    }

    /// Move to the nearest visible node in a direction.
    ///
    /// `(dx, dy)` is a unit vector. Each candidate is decomposed into distance
    /// *along* that direction and distance *across* it; anything with a
    /// non-positive `along` is behind the cursor and skipped. The score
    /// `along + across * 2.0` weights sideways displacement double, so the
    /// cursor prefers something straight ahead over something closer but well
    /// off-axis — otherwise arrow keys feel like they teleport.
    fn move_towards(&mut self, dx: f64, dy: f64) {
        let visible = self.visible_indices();
        if visible.is_empty() {
            return;
        }
        if !self.node_visible(self.selected) {
            self.selected = visible[0];
            return;
        }
        let (sx, sy) = self.pos[self.selected];
        let mut best: Option<(f64, usize)> = None;
        for i in visible {
            if i == self.selected {
                continue;
            }
            let (x, y) = self.pos[i];
            let (ox, oy) = (x - sx, y - sy);
            let along = ox * dx + oy * dy;
            if along <= 0.0 {
                continue; // behind us
            }
            let across = (ox * dy - oy * dx).abs();
            // Prefer straight ahead, then near. Weighting the sideways part
            // stops the cursor leaping across the graph to a distant node
            // that happens to be a degree off the axis.
            let score = along + across * 2.0;
            if best.is_none_or(|(b, _)| score < b) {
                best = Some((score, i));
            }
        }
        if let Some((_, i)) = best {
            self.selected = i;
        }
    }

    /// `Tab` / `Shift+Tab`: step through every visible node in index order,
    /// wrapping. The exhaustive alternative to spatial movement, for when a
    /// node is not reachable by arrow keys.
    fn cycle(&mut self, forward: bool) {
        let visible = self.visible_indices();
        if visible.is_empty() {
            return;
        }
        let at = visible.iter().position(|i| *i == self.selected);
        let next = match (at, forward) {
            (Some(p), true) => (p + 1) % visible.len(),
            (Some(p), false) => (p + visible.len() - 1) % visible.len(),
            (None, _) => 0,
        };
        self.selected = visible[next];
    }

    // ---- keys -------------------------------------------------------------

    /// Handle one keypress and say what, if anything, `App` should do.
    ///
    /// Takes what the key *meant* rather than the key: `App` resolves it, and
    /// anything the map has no binding for — every global chord, and the `/`
    /// that opens the bar — arrives as `None` and is left alone.
    pub fn on_key(&mut self, action: Option<Action>) -> Intent {
        let Some(action) = action else {
            return Intent::None;
        };
        match action {
            Action::Back => return Intent::Close,
            Action::Open => {
                if let Some(n) = self.selected_node() {
                    return Intent::Open(n.path.clone());
                }
            }
            Action::Left => self.move_towards(-1.0, 0.0),
            Action::Right => self.move_towards(1.0, 0.0),
            // Screen coordinates run downwards; the layout runs upwards.
            Action::Up => self.move_towards(0.0, 1.0),
            Action::Down => self.move_towards(0.0, -1.0),
            Action::MapNext => self.cycle(true),
            Action::MapPrevious => self.cycle(false),
            Action::MapWikilinks => self.toggle_kind(0),
            Action::MapLinks => self.toggle_kind(1),
            Action::MapCalls => self.toggle_kind(2),
            Action::Refresh => return Intent::Rebuild,
            _ => {}
        }
        Intent::None
    }

    /// Narrow the map to the paths containing `query`, and keep the cursor on
    /// something that is still drawn.
    ///
    /// Called by the bar. The map has no filter box of its own: filtering the
    /// map and searching the project are the same act, so they are the same
    /// field in the same place on screen — see `App::open_bar`.
    pub fn set_filter(&mut self, query: &str) {
        self.filter = query.trim().to_string();
        let wanted = self.filter.to_lowercase();
        for (shown, n) in self.shown.iter_mut().zip(&self.graph.nodes) {
            *shown = wanted.is_empty() || n.rel.to_lowercase().contains(&wanted);
        }
        self.ensure_selection();
    }

    /// Turn one kind of connection on or off, and make sure the cursor is
    /// still on something that is drawn.
    fn toggle_kind(&mut self, i: usize) {
        self.kinds[i] = !self.kinds[i];
        self.ensure_selection();
    }

    /// Keep the cursor on something that is actually drawn.
    fn ensure_selection(&mut self) {
        if !self.node_visible(self.selected) {
            self.select_first_visible();
        }
    }

    /// One-line summary for the pane title.
    pub fn summary(&self) -> String {
        let shown = self.shown.iter().filter(|s| **s).count();
        // Connections, not edges: the picture draws one line per pair of
        // files, so counting per-symbol edges here would promise lines that
        // are not there.
        let links = self.links().len();
        let hidden = self.graph.nodes.len() - shown;
        let mut out = format!("{shown}/{} files | {links} links", self.graph.nodes.len());
        if hidden > 0 {
            out.push_str(&format!(" | {hidden} hidden"));
        }
        out
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::map::testing::*;
    use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};

    // ---- what is shown ----------------------------------------------------

    #[test]
    fn turning_off_an_edge_kind_never_takes_a_file_off_the_map() {
        let (_td, mut view) = fixture();
        let all: Vec<String> = visible_names(&view).iter().map(|s| s.to_string()).collect();
        assert!(all.iter().any(|r| r == "notes/design.md"));

        // The notes are held on only by wikilinks, so switching those off
        // leaves nothing reaching them — but they are still files in the
        // project, and the map still has to show them.
        view.kinds[kind_index(EdgeKind::Wikilink)] = false;
        assert_eq!(
            visible_names(&view),
            all,
            "what a connection kind changes is the arrangement, not the census"
        );
        assert!(
            !view.connected(
                view.graph
                    .nodes
                    .iter()
                    .position(|n| n.rel == "notes/design.md")
                    .unwrap()
            )
        );
    }

    #[test]
    fn the_filter_narrows_to_matching_paths() {
        let (_td, mut view) = fixture();
        view.set_filter("src/");
        let shown = visible_names(&view);
        assert!(shown.iter().all(|r| r.starts_with("src/")), "{shown:?}");
        assert!(!shown.is_empty());
    }

    #[test]
    fn the_summary_counts_what_is_actually_drawn() {
        let (_td, view) = fixture();
        assert!(view.summary().contains("/5 files"), "{}", view.summary());
        assert!(view.summary().starts_with("5/5"), "{}", view.summary());
    }

    #[test]
    fn connections_are_split_into_outgoing_and_incoming() {
        let (_td, view) = fixture();
        let main = view
            .graph
            .nodes
            .iter()
            .position(|n| n.rel == "src/main.py")
            .unwrap();
        let (out, incoming) = view.connections(main);
        assert!(!out.is_empty(), "main.py calls utils.load");
        assert!(incoming.is_empty(), "nothing points at main.py");
        assert!(out.iter().all(|e| e.from == main));
    }

    // ---- moving around ----------------------------------------------------

    #[test]
    fn arrows_move_to_the_nearest_file_in_that_direction() {
        let (_td, mut view) = fixture();
        // Put two nodes in known places and check the cursor goes the right way.
        view.selected = 0;
        view.pos[0] = (0.0, 0.0);
        view.pos[1] = (100.0, 0.0);
        view.pos[2] = (-100.0, 0.0);
        view.pos[3] = (0.0, 100.0);
        view.pos[4] = (0.0, -100.0);

        view.on_key(act(k(KeyCode::Right)));
        assert_eq!(view.selected, 1);
        view.selected = 0;
        view.on_key(act(k(KeyCode::Left)));
        assert_eq!(view.selected, 2);
        view.selected = 0;
        view.on_key(act(k(KeyCode::Up)));
        assert_eq!(view.selected, 3, "up is up on screen");
        view.selected = 0;
        view.on_key(act(k(KeyCode::Down)));
        assert_eq!(view.selected, 4);
    }

    #[test]
    fn moving_towards_nothing_leaves_the_cursor_alone() {
        let (_td, mut view) = fixture();
        view.selected = 0;
        view.pos = vec![
            (0.0, 0.0),
            (-50.0, 0.0),
            (-60.0, 0.0),
            (-70.0, 0.0),
            (-80.0, 0.0),
        ];
        view.on_key(act(k(KeyCode::Right)));
        assert_eq!(view.selected, 0, "everything is to the left");
    }

    #[test]
    fn tab_cycles_through_every_visible_file_and_wraps() {
        let (_td, mut view) = fixture();
        let visible = view.visible_indices();
        view.selected = visible[0];
        for _ in 0..visible.len() {
            view.on_key(act(k(KeyCode::Tab)));
        }
        assert_eq!(view.selected, visible[0], "a full lap comes back round");
    }

    #[test]
    fn the_cursor_never_sits_on_something_hidden() {
        let (_td, mut view) = fixture();
        let alone = view
            .graph
            .nodes
            .iter()
            .position(|n| n.rel == "notes/alone.md")
            .unwrap();
        view.selected = alone;

        // The filter is the only thing that can take a file off the map now.
        view.set_filter("utils");
        assert!(
            view.node_visible(view.selected),
            "the cursor should have moved to something still drawn"
        );
    }

    #[test]
    fn a_file_nothing_reaches_is_still_on_the_map() {
        let (_td, view) = fixture();
        let alone = view
            .graph
            .nodes
            .iter()
            .position(|n| n.rel == "notes/alone.md")
            .unwrap();
        assert!(
            view.node_visible(alone),
            "a file with no links is part of the project too"
        );
        assert!(!view.connected(alone), "it just has nothing pointing at it");
    }

    #[test]
    fn unconnected_files_are_filed_under_their_own_heading_last() {
        let (_td, mut view) = fixture();
        let place = view.place(120, 60);
        let headings: Vec<&str> = place.folders.iter().map(|f| f.label.as_str()).collect();

        assert_eq!(
            headings.last(),
            Some(&"unconnected"),
            "and it comes after the folders, not among them: {headings:?}"
        );
        let lonely = place
            .folders
            .last()
            .expect("there is an unconnected heading");
        assert_eq!(lonely.files, 1, "just alone.md");
        assert!(
            headings.contains(&"notes/") && headings.contains(&"src/"),
            "the folders are still there: {headings:?}"
        );
    }

    #[test]
    fn turning_a_connection_kind_off_moves_its_files_to_unconnected() {
        let (_td, mut view) = fixture();
        let before = view.place(120, 60);
        let notes = before
            .folders
            .iter()
            .find(|f| f.label == "notes/")
            .expect("design and architecture link to each other")
            .files;
        assert_eq!(notes, 2, "alone.md is already elsewhere");

        // With wikilinks hidden, nothing reaches the two notes either.
        view.toggle_kind(0);
        let after = view.place(120, 60);
        let lonely = after
            .folders
            .iter()
            .find(|f| f.label == "unconnected")
            .expect("still a heading for them");
        assert_eq!(
            lonely.files, 3,
            "the map should say which files it has nothing to tell you about"
        );
    }

    // ---- keys -------------------------------------------------------------

    #[test]
    fn escape_closes_the_graph_and_nothing_else_does() {
        let (_td, mut view) = fixture();
        assert!(matches!(view.on_key(act(k(KeyCode::Esc))), Intent::Close));
        // `m` and `q` used to close it too. One window, one way out.
        for key in [ch('m'), ch('q')] {
            let (_td, mut view) = fixture();
            assert!(!matches!(view.on_key(act(key)), Intent::Close), "{key:?}");
        }
    }

    #[test]
    fn enter_asks_for_the_selected_file_to_be_opened() {
        let (td, mut view) = fixture();
        view.selected = view.visible_indices()[0];
        let want = view.graph.nodes[view.selected].path.clone();
        match view.on_key(act(k(KeyCode::Enter))) {
            Intent::Open(p) => {
                assert_eq!(p, want);
                assert!(p.starts_with(td.path()));
            }
            _ => panic!("Enter should open the file"),
        }
    }

    #[test]
    fn the_number_keys_toggle_edge_kinds() {
        let (_td, mut view) = fixture();
        assert!(view.kinds.iter().all(|k| *k));
        view.on_key(act(ch('3')));
        assert!(!view.kinds[kind_index(EdgeKind::Call)]);
        view.on_key(act(ch('3')));
        assert!(view.kinds[kind_index(EdgeKind::Call)]);
    }

    #[test]
    fn a_filter_narrows_the_map_and_clearing_it_brings_everything_back() {
        let (_td, mut view) = fixture();
        let all = visible_names(&view).len();

        view.set_filter("src");
        assert!(visible_names(&view).iter().all(|r| r.contains("src")));
        assert!(visible_names(&view).len() < all, "something was hidden");

        view.set_filter("");
        assert_eq!(visible_names(&view).len(), all, "and comes back");
    }

    #[test]
    fn a_key_the_map_does_not_use_does_nothing_at_all() {
        let (_td, mut view) = fixture();
        // `/` is the bar's, and the bar is opened by `App` before the map is
        // ever asked — so as far as the map is concerned it means nothing.
        assert!(matches!(view.on_key(None), Intent::None));
        assert!(matches!(view.on_key(act(ch('q'))), Intent::None));
        assert!(view.filter.is_empty());
    }

    #[test]
    fn control_chords_are_ignored_rather_than_acted_on() {
        let (_td, mut view) = fixture();
        let ctrl_c = KeyEvent {
            modifiers: KeyModifiers::CONTROL,
            ..ch('c')
        };
        assert!(matches!(view.on_key(act(ctrl_c)), Intent::None));
    }

    #[test]
    fn r_lays_the_graph_out_again_to_the_same_place() {
        let (_td, mut view) = fixture();
        let before = view.pos.clone();
        view.on_key(act(ch('r')));
        for (a, b) in before.iter().zip(view.pos.iter()) {
            assert!((a.0 - b.0).abs() < 1e-9 && (a.1 - b.1).abs() < 1e-9);
        }
    }
}

