//! The two single-row strips: the bar, and the status line.
//!
//! Neither knows where it is. [`super::draw`] hands each one a row — the bar
//! at the top, the status line at the bottom — and they fill it.
//!
//! The bar is one field that is three things: a search when it starts with
//! anything, a command when it starts with the sigil, and the map's filter
//! when the map is the window behind it. It decides which keystroke by
//! keystroke rather than being opened in a mode, which is why there is only
//! one of it — and why there is no separate filter box on the map.

use ratatui::Frame;
use ratatui::layout::Rect;
use ratatui::style::Modifier;
use ratatui::text::{Line, Span};
use ratatui::widgets::Paragraph;
use unicode_width::UnicodeWidthStr;

use super::parts::split_at_char;

use crate::app::{App, ConfirmKind, Focus, GitFocus, Mode, Window};
use crate::config::keys::Action;
use crate::files::size;

/// The search (`/`) or command (`:`) line.
///
/// Draws its own block cursor as a reversed span, because the terminal has
/// only one real cursor and the editor pane has a stronger claim on it.
pub(super) fn draw_bar(f: &mut Frame, app: &App, area: Rect) {
    let Mode::Bar(b) = &app.mode else { return };
    let pal = app.palette;
    // One bar, so the sigil is a readout rather than a mode you chose: it
    // follows what has been typed, and changes under you the moment the line
    // starts or stops with a `*`.
    let command = b.is_command();
    let sigil = if command { " * " } else { " / " };
    // The sigil is drawn as its own block, so the typed `*` is not shown a
    // second time — and the cursor has to shift back past it to match.
    let (text, cursor) = if command {
        (b.command(), b.cursor.saturating_sub(1))
    } else {
        (b.input.as_str(), b.cursor)
    };
    let (before, after) = split_at_char(text, cursor);

    // What Tab would fill in, shown in gray ahead of the cursor. Only at the
    // end of the line: in the middle of one it would read as text that is
    // already there rather than as an offer.
    let ghost = if command && b.cursor == b.input.chars().count() {
        crate::app::completion_for(
            b,
            app.tree.root_path(),
            app.config.show_hidden,
            &app.plugins.commands(),
            &app.known_names(),
        )
        .unwrap_or_default()
    } else {
        String::new()
    };

    let hint = if command {
        "  Tab or → complete · Enter run · Esc close"
    } else if app.window == Window::Map {
        "  narrowing the map · Enter keep · Esc clear"
    } else if b.results.is_empty() {
        "  names and contents · * for a command · Esc close"
    } else {
        "  up/down pick · Enter jump · Esc close"
    };
    // The real cursor lives in the editor, so the bar draws its own — on the
    // next character of the line, or on the first character being offered when
    // there is nothing left of the line. Sitting it on a blank instead would
    // push the offer along by a space and break the word in half.
    let (cursor_char, ghost) = match (after.chars().next(), ghost.chars().next()) {
        (Some(c), _) => (c.to_string(), ghost),
        (None, Some(c)) => (c.to_string(), ghost.chars().skip(1).collect()),
        (None, None) => (" ".to_string(), String::new()),
    };
    let line = Line::from(vec![
        Span::styled(sigil, pal.text.add_modifier(Modifier::REVERSED)),
        Span::styled(before, pal.text),
        Span::styled(cursor_char, pal.text.add_modifier(Modifier::REVERSED)),
        Span::styled(after.chars().skip(1).collect::<String>(), pal.text),
        Span::styled(ghost, pal.dim),
        Span::styled(hint, pal.dim),
    ]);
    // Under a command, what Enter would do with it — or why it would not.
    // Read off the same plan Enter carries out, so the two cannot differ.
    let said = match &b.plan {
        Some(Ok(does)) => Some(Line::from(vec![
            Span::styled("   ↳ ", pal.dim),
            Span::styled(does.clone(), pal.text),
        ])),
        Some(Err(why)) => Some(Line::from(vec![
            Span::styled("   ? ", pal.dim),
            Span::styled(why.clone(), pal.marker),
        ])),
        None => None,
    };
    let lines: Vec<Line> = std::iter::once(line).chain(said).collect();
    f.render_widget(Paragraph::new(lines), area);
}

/// How many rows the bar wants: one for the line, and one more under a
/// command for what it would do.
pub(super) fn bar_height(app: &App) -> u16 {
    match &app.mode {
        Mode::Bar(b) if b.is_command() && b.plan.is_some() => 2,
        _ => 1,
    }
}

// ---- status line ----------------------------------------------------------

/// The status line: prompts, confirmations, or the ordinary message plus
/// context-sensitive hints.
///
/// Hints are dropped before the readout at the end when the window is too
/// narrow for both, so the line degrades gracefully instead of wrapping or
/// being clipped mid-word.
pub(super) fn draw_status(f: &mut Frame, app: &App, area: Rect) {
    let pal = app.palette;
    let line = match &app.mode {
        // The update question has a window of its own; under it, the line
        // only needs to say which two keys answer it.
        Mode::Confirm(c) if matches!(c.kind, ConfirmKind::Update(_)) => Line::from(vec![
            Span::styled(" ! ", pal.marker.add_modifier(Modifier::REVERSED)),
            Span::styled(" y update now · n not now", pal.marker),
        ]),
        Mode::Confirm(c) => Line::from(vec![
            Span::styled(" ! ", pal.marker.add_modifier(Modifier::REVERSED)),
            Span::styled(format!(" {}", c.message), pal.marker),
        ]),
        _ => {
            if app.window == Window::Map {
                let line = Line::from(vec![
                    Span::styled(format!(" {}", app.status), pal.text),
                    Span::styled(
                        "   arrows move | Enter open | 1-3 kinds | / filter | Esc back",
                        pal.dim,
                    ),
                ]);
                f.render_widget(Paragraph::new(line).style(pal.text), area);
                return;
            }
            if app.window == Window::Source {
                // What the arrows do here depends on which half has them, and
                // a hint naming the other half's keys is worse than none.
                let hints = match app.git.focus {
                    GitFocus::Message => "Ctrl+S commit | Esc put it down",
                    GitFocus::Diff => "up/down scroll | left back to the changes",
                    GitFocus::List => "Enter stage | Tab open | r refresh | Esc back",
                };
                let line = Line::from(vec![
                    Span::styled(format!(" {}", app.status), pal.text),
                    Span::styled(format!("   {hints}"), pal.dim),
                ]);
                f.render_widget(Paragraph::new(line).style(pal.text), area);
                return;
            }
            let hints: String = match (&app.mode, app.focus) {
                // Those two windows carry their own keys along their bottom
                // edge, and saying them twice is just more to read.
                (Mode::Settings(_) | Mode::Keybinds(_), _) => String::new(),
                (Mode::Bar(_), _) => "Esc close".into(),
                // Written out in full rather than as `^S` — this line is the
                // first place most people meet these keys, and a caret is a
                // thing you have to already know.
                //
                // The window keys are read from the live keymap rather than
                // written down here, so a rebinding shows here too. A hint
                // has to name the key that will actually work.
                (_, Focus::Tree) => format!(
                    "/ search | {} git | {} map",
                    key_name(app, Action::WindowSource),
                    key_name(app, Action::WindowMap)
                ),
                (_, Focus::Editor) => "Ctrl+S save | Ctrl+Z undo | Ctrl+K cut | Esc back".into(),
            };
            let pos = position_readout(app);
            let room = area.width as usize;
            let mut spans = vec![
                Span::styled(format!(" {}", app.status), pal.text),
                Span::raw("   "),
            ];
            let used: usize = spans.iter().map(|s| s.content.width()).sum();
            if used + hints.width() + pos.width() + 3 < room {
                spans.push(Span::styled(hints, pal.dim));
            }
            let used: usize = spans.iter().map(|s| s.content.width()).sum();
            if used + pos.width() + 1 < room {
                spans.push(Span::raw(" ".repeat(room - used - pos.width() - 1)));
                spans.push(Span::styled(pos, pal.dim));
            }
            Line::from(spans)
        }
    };
    f.render_widget(Paragraph::new(line).style(app.palette.text), area);
}

/// The first key bound to an action, written the way someone would say it.
///
/// Read from the live keymap, so a hint names what will actually work — after
/// a rebinding, and on a terminal that was given a different keyboard.
fn key_name(app: &App, action: Action) -> String {
    let spec = app.keymap.spec(action);
    let first = spec.split_whitespace().next().unwrap_or_default();
    first
        .split('+')
        .map(|part| {
            let mut chars = part.chars();
            match chars.next() {
                Some(c) => c.to_uppercase().collect::<String>() + chars.as_str(),
                None => String::new(),
            }
        })
        .collect::<Vec<_>>()
        .join("+")
}

/// The right-hand end of the status line: how much disk the thing under the
/// cursor takes, and — while editing — where in the file the cursor is.
///
/// The size is there for every file and every folder, because "how big is
/// this" is a question you ask of anything you are looking at. What used to be
/// here was the cursor's number in the row list, which answered a question
/// nobody had: the cursor is already visible, and the rows are already
/// counted by the browser it sits in.
fn position_readout(app: &App) -> String {
    // Each window counts something different, and counting the browser's rows
    // while looking at another one is a number that means nothing.
    match app.window {
        Window::Source => match app.git.current() {
            Some((change, _)) => format!("{} ", change.code.word()),
            None => String::new(),
        },
        Window::Map => String::new(),
        Window::Main => {
            let size = app.cursor_size.map(size::human).unwrap_or_default();
            match app.active_buffer() {
                // While editing, both: the line and column move with every
                // keypress and the size hardly ever, so the steady number goes
                // on the outside where it will not be read as part of the one
                // that is moving.
                Some(ed) if app.focus == Focus::Editor => {
                    format!("{}:{}  {size} ", ed.cursor_line + 1, ed.cursor_col + 1)
                }
                _ => format!("{size} "),
            }
        }
    }
}

// ---- overlays -------------------------------------------------------------

