//! The help overlay: every key and every command, on one screen.
//!
//! The table is generated from the live [`Keymap`], never from a written list,
//! so a rebound key shows its new binding here and a new action cannot be
//! added without appearing. That is the whole point of the indirection in
//! [`crate::config::keys`]: there is one source of truth for what a key does
//! and this is a view of it.
//!
//! Laid out in two columns when the window is wide enough for both and one
//! when it is not, which is why the column widths are measured rather than
//! fixed.

use ratatui::Frame;
use ratatui::layout::{Constraint, Direction, Layout, Rect};
use ratatui::style::Modifier;
use ratatui::text::{Line, Span};
use ratatui::widgets::{Block, Borders, Clear, Paragraph};
use unicode_width::UnicodeWidthStr;

use super::parts::centered;

use crate::app::App;
use crate::config::Palette;
use crate::config::keys::{Action, Keymap};

/// One row of the keys half of `?`.
///
/// Descriptions are labels of a word or two, not sentences. The window has to
/// hold every binding at once, and its width is set by the longest of them, so
/// a phrase here costs a column on every other row. This is the thing you
/// glance at; the keybinds window has the whole list, one action a row.
enum KeyRow {
    Heading(&'static str),
    /// A gap between sections.
    Blank,
    /// The keys are looked up in the live keymap when the window is drawn, so
    /// a rebinding shows here as well as in the keybinds window. Several
    /// actions on one row read as one idea — "move the cursor" is up and down.
    Bound(&'static [Action], &'static str),
    /// Like [`KeyRow::Bound`], but the keys are folded together rather than
    /// listed one action at a time — see [`merge`]. For the rows where four
    /// actions are one gesture, and writing `ctrl+` four times says nothing
    /// the first one did not.
    Merged(&'static [Action], &'static str),
    /// A row whose keys cannot be rebound, and so cannot change.
    Fixed(&'static str, &'static str),
}

use KeyRow::{Blank, Bound, Fixed, Heading, Merged};

/// The keys half of `?`, in the order someone learning tiny needs them.
///
/// Moving first, because that is what you do before anything else; then the
/// things you do to a file; then the windows; then the keys only git and the
/// map have. Each key appears once: Enter is "open" in the browser and on the
/// map and "stage" in git, and that is one row saying so rather than three.
const KEYS: &[KeyRow] = &[
    Heading("MOVE"),
    Merged(
        &[Action::Up, Action::Down, Action::Left, Action::Right],
        "move",
    ),
    Merged(
        &[
            Action::First,
            Action::Last,
            Action::EditorLineStart,
            Action::EditorLineEnd,
        ],
        "ends",
    ),
    Merged(&[Action::PageUp, Action::PageDown], "page"),
    Merged(&[Action::EditorWordLeft, Action::EditorWordRight], "word"),
    Merged(
        &[Action::EditorDocStart, Action::EditorDocEnd],
        "top · bottom",
    ),
    Bound(&[Action::Open], "open · stage"),
    Bound(&[Action::Back], "back · quit"),
    Fixed("wheel", "scroll"),
    Blank,
    Heading("FILES"),
    Bound(&[Action::Save], "save"),
    Bound(&[Action::EditorUndo, Action::EditorRedo], "undo · redo"),
    Bound(&[Action::EditorDeleteLine], "delete line"),
    Bound(&[Action::Copy, Action::Paste], "copy · paste"),
    Bound(&[Action::TreeHidden], "dotfiles"),
    Blank,
    Heading("WINDOWS"),
    Bound(&[Action::Bar], "search · *command"),
    Bound(&[Action::WindowSource], "git"),
    Bound(&[Action::WindowMap], "map"),
    Bound(&[Action::NewWindow], "new window"),
    Merged(
        &[Action::ToggleTreePane, Action::Narrower, Action::Wider],
        "browser · width",
    ),
    Bound(&[Action::Help], "help"),
    Bound(&[Action::Quit], "quit"),
    Blank,
    Heading("GIT · MAP"),
    Merged(&[Action::SourceOpen, Action::MapNext], "edit · next file"),
    Bound(&[Action::Refresh], "refresh"),
    Merged(
        &[Action::MapWikilinks, Action::MapLinks, Action::MapCalls],
        "link kinds",
    ),
];

/// The keys of several actions, folded into one field.
///
/// Two rules, and both are about the same thing: four keys that are one
/// gesture should read as one gesture. A modifier every key shares is written
/// once at the front, so the row for "five at a time" says `ctrl+up down left
/// right` rather than repeating `ctrl+` four times. And named keys come before
/// letters, so the arrows arrive as a group and the `i k j l` that stand in for
/// them arrive as another.
///
/// Everything is read out of the live keymap, so a rebinding shows here. A
/// rebinding that breaks the shared modifier simply falls back to a plain list,
/// which is longer but never wrong.
fn merge(keymap: &Keymap, actions: &[Action]) -> String {
    // Group by the modifier prefix — everything up to and including the last
    // `+` — keeping the order the groups first appeared in.
    let mut groups: Vec<(String, Vec<String>, Vec<String>)> = Vec::new();
    for spec in actions.iter().flat_map(|a| keymap.keys(*a)) {
        let written = spec.to_string();
        let cut = written.rfind('+').map_or(0, |i| i + 1);
        let (mods, base) = written.split_at(cut);
        let slot = match groups.iter().position(|(m, ..)| m == mods) {
            Some(i) => &mut groups[i],
            None => {
                groups.push((mods.to_string(), Vec::new(), Vec::new()));
                groups.last_mut().expect("just pushed")
            }
        };
        // A single character is a letter standing in for an arrow; anything
        // longer is a named key. They read better apart than interleaved.
        let half = if base.chars().count() == 1 {
            &mut slot.2
        } else {
            &mut slot.1
        };
        // Once each. Four actions share `Home` and `End` between them — the
        // ends of a list and the ends of a line are the same two keys in two
        // panes — and a row reading `home end home end` says nothing twice.
        if !half.iter().any(|k| k == base) {
            half.push(base.to_string());
        }
    }
    let mut out: Vec<String> = Vec::new();
    for (mods, named, letters) in groups {
        for half in [named, letters] {
            if !half.is_empty() {
                out.push(format!("{mods}{}", half.join(" ")));
            }
        }
    }
    out.join("  ")
}

/// The keys half of `?`, resolved against what the keys actually do now.
fn key_rows(keymap: &Keymap) -> Vec<(String, String)> {
    KEYS.iter()
        .map(|row| match row {
            Heading(title) => (String::new(), (*title).to_string()),
            Blank => (String::new(), String::new()),
            Fixed(keys, desc) => ((*keys).to_string(), (*desc).to_string()),
            Merged(actions, desc) => (merge(keymap, actions), (*desc).to_string()),
            Bound(actions, desc) => {
                // An action bound to nothing contributes nothing, rather than
                // an empty gap in the middle of the row.
                let keys: Vec<String> = actions
                    .iter()
                    .map(|a| keymap.spec(*a))
                    .filter(|s| !s.is_empty())
                    .collect();
                (keys.join("  "), (*desc).to_string())
            }
        })
        .collect()
}

/// The right half of the `?` window: every command, as an example of saying it.
///
/// Written with the star, because that is what reaches them — there is one bar
/// and this is how you tell it you meant a command. Examples rather than
/// templates, because a command is a sentence and a sentence is learned from
/// one: the other ways of saying each (`go to`, `open`, `cp`, `remove`...)
/// work too, and the line under the bar says what any of them will do.
///
/// A command whose words already say what it does has no description: the
/// column is for the few that need one. A new verb belongs here as well as in
/// `sentence`.
const COMMANDS: &[(&str, &str)] = &[
    ("", "COMMANDS"),
    ("*goto line 42", ""),
    ("*goto function main", "or word, text"),
    ("*goto heading install", ""),
    ("*goto file notes.md", "or folder"),
    ("*goto word todo in a.md", "in: just there"),
    ("*copy temp.txt to notes", ""),
    ("*move temp.txt to notes", ""),
    ("*rename old.md to new.md", ""),
    ("*new notes/today.md", ""),
    ("*new folder ideas", ""),
    ("*delete old.md", ""),
    ("*replace hi with hello", "every file"),
    ("*replace hi with hey in a.md", "one file"),
    ("*reload", ""),
    ("*commit [message]", "what is staged"),
    ("*set tab_width to 2", ""),
    ("*config", "settings · keys"),
    ("*update", "newest tiny"),
];

/// The keymap overlay. Scrollable, because the full list does not fit a short
/// terminal — the footer says which of the two situations you are in.
pub(super) fn draw_help(f: &mut Frame, app: &App, area: Rect, pal: &Palette, scroll: usize) {
    // Keys on the left, commands on the right, so `?` answers both halves of
    // "how do I do this" at once. Every width here is measured from the tables
    // rather than written down, so adding a row with a long description
    // widens the window instead of quietly losing the end of the line.
    // The keys are read out of the live keymap, so a rebinding shows here and
    // not only in the window that made it.
    let keys = key_rows(&app.keymap);
    let mut commands: Vec<(String, String)> = COMMANDS
        .iter()
        .map(|(a, b)| ((*a).to_string(), (*b).to_string()))
        .collect();
    // What the plugins added, under the name of the plugin that added each —
    // they are commands like any other, and this is where commands are found.
    let added = app.plugins.commands();
    if !added.is_empty() {
        commands.push((String::new(), String::new()));
        commands.push((String::new(), "PLUGINS".to_string()));
        for name in added {
            let owner = app.plugins.command_owner(&name).unwrap_or_default();
            commands.push((format!("*{name}"), owner));
        }
    }
    let (keys_field, keys_w) = (field_width(&keys), natural_width(&keys));
    let (cmds_field, cmds_w) = (field_width(&commands), natural_width(&commands));

    // One column: the two tables run together with a blank line between, which
    // makes one wider field for both and so has to be measured on the joined
    // list rather than on either half.
    let stacked: Vec<(String, String)> = keys
        .iter()
        .cloned()
        .chain(std::iter::once((String::new(), String::new())))
        .chain(commands.iter().cloned())
        .collect();

    // Two columns need both of them whole, plus the border and a gutter.
    let two_up = (keys_w + cmds_w + 5) as u16 <= area.width.saturating_sub(2);
    let rows = if two_up {
        keys.len().max(commands.len())
    } else {
        stacked.len()
    };
    let width = if two_up {
        (keys_w + cmds_w + 5) as u16
    } else {
        (natural_width(&stacked) + 2) as u16
    };
    let popup = centered(area, width, rows as u16 + 2);
    let scrolls = (popup.height as usize).saturating_sub(2) < rows;

    f.render_widget(Clear, popup);
    let block = Block::default()
        .borders(Borders::ALL)
        .border_style(pal.border_focus)
        .title(Line::from(Span::styled(
            " Help ",
            pal.text.add_modifier(Modifier::BOLD),
        )))
        .title_bottom(Line::from(Span::styled(
            if scrolls {
                " up/down scroll · any other key closes "
            } else {
                " any key closes "
            },
            pal.dim,
        )));
    let inner = block.inner(popup);
    f.render_widget(block, popup);

    let height = inner.height as usize;
    let scroll = scroll.min(rows.saturating_sub(height));
    if two_up {
        let halves = Layout::default()
            .direction(Direction::Horizontal)
            .constraints([Constraint::Length(keys_w as u16 + 2), Constraint::Min(0)])
            .split(inner);
        f.render_widget(
            help_column(&keys, scroll, height, keys_field, pal),
            halves[0],
        );
        f.render_widget(
            help_column(&commands, scroll, height, cmds_field, pal),
            halves[1],
        );
    } else {
        let field = field_width(&stacked);
        f.render_widget(help_column(&stacked, scroll, height, field, pal), inner);
    }
}

/// How wide the first field has to be for every row of `rows` to line up.
fn field_width(rows: &[(String, String)]) -> usize {
    rows.iter()
        .filter(|(keys, _)| !keys.is_empty())
        .map(|(keys, _)| keys.width())
        .max()
        .unwrap_or(0)
}

/// How wide the column has to be for no row of it to be cut off. Headings and
/// spacers span the whole column, so they count too.
fn natural_width(rows: &[(String, String)]) -> usize {
    let field = field_width(rows);
    rows.iter()
        .map(|(keys, desc)| {
            if keys.is_empty() {
                desc.width()
            } else {
                field + 2 + desc.width()
            }
        })
        .max()
        .unwrap_or(0)
}

/// One column of the `?` window, already scrolled and clipped to `height`.
fn help_column(
    rows: &[(String, String)],
    scroll: usize,
    height: usize,
    field: usize,
    pal: &Palette,
) -> Paragraph<'static> {
    let lines: Vec<Line> = rows
        .iter()
        .skip(scroll)
        .take(height)
        .map(|(keys, desc)| {
            if keys.is_empty() {
                Line::from(Span::styled(desc.clone(), pal.heading))
            } else {
                Line::from(vec![
                    Span::styled(
                        format!("{keys:<field$}  "),
                        pal.text.add_modifier(Modifier::BOLD),
                    ),
                    Span::styled(desc.clone(), pal.dim),
                ])
            }
        })
        .collect();
    Paragraph::new(lines)
}

files.src/ui/ink.rs:
//! A grid of box-drawing characters, and the routing that fills it.
//!
//! Terminal line art has one hard problem: two lines that cross have to become
//! a junction glyph, not one line written over the other. [`Ink`] solves it by
//! storing a *direction bitmask* per cell — up, down, left, right — instead of
//! a character. Drawing a line ORs bits in, and the glyph is only chosen at
//! the end, from whatever bits a cell ended up with. A cell that acquired
//! `LEFT | RIGHT | UP` becomes `┴` without anything having to notice that two
//! separate lines met there.
//!
//! # Why lines travel in channels
//!
//! A route that turns at the midpoint between two boxes lands *inside* a third
//! one whenever the two are not neighbors, and since boxes are drawn last the
//! line then runs behind it and reads as broken. So routes are not allowed to
//! turn wherever they like: they turn in [`crate::map::layout::Channels`], the
//! rows and columns that the layout guarantees are clear of every box. Every
//! line out of one file also shares a trunk, so a file with eight connections
//! produces one bundle leaving it rather than eight separate departures.

use ratatui::style::{Modifier, Style};
use ratatui::text::{Line, Span};

use crate::config::{Markers, Palette};
use crate::map::layout::{Channels, Placed};

/// How brightly one cell of the graph is drawn.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(super) enum InkStyle {
    /// A folder heading. Not part of the picture — it names the group of
    /// boxes under it — so it is written into the grid rather than over the
    /// finished row, and a line running past it keeps the cells it had.
    Folder,
    /// Everything not connected to the cursor.
    Far,
    /// A file the one under the cursor reaches: it links to or calls this.
    Out,
    /// A file that reaches the one under the cursor.
    In,
    /// The file under the cursor itself.
    Selected,
}

/// The characters the graph is drawn out of.
///
/// Two sets, chosen by the `markers` setting, so a terminal with no box-drawing
/// characters gets a picture made of `+`, `-` and `|` rather than a screen of
/// replacement glyphs. Boxes use rounded corners where they exist, which keeps
/// them visually separate from the sharp corners a line turns with.
pub(super) struct Glyphs {
    /// Indexed by the direction bits a line leaves a cell by.
    lines: [char; 16],
    corners: [char; 4],
    horizontal: char,
    vertical: char,
}

impl Glyphs {
    pub(super) fn for_markers(markers: Markers) -> Self {
        match markers {
            Markers::Arrows => Self {
                lines: [
                    ' ', '│', '│', '│', '─', '┘', '┐', '┤', '─', '└', '┌', '├', '─', '┴', '┬', '┼',
                ],
                corners: ['╭', '╮', '╰', '╯'],
                horizontal: '─',
                vertical: '│',
            },
            Markers::Ascii => Self {
                lines: [
                    ' ', '|', '|', '|', '-', '+', '+', '+', '-', '+', '+', '+', '-', '+', '+', '+',
                ],
                corners: ['+', '+', '+', '+'],
                horizontal: '-',
                vertical: '|',
            },
        }
    }
}

// Which way a line leaves a cell. Kept as bits so two lines crossing produce
// the right junction on their own, without anyone having to notice they met.
const UP: u8 = 1;
const DOWN: u8 = 2;
const LEFT: u8 = 4;
const RIGHT: u8 = 8;

/// The character grid the graph is composed on before it becomes a widget.
///
/// Two layers: lines, held as direction bits so crossings merge themselves,
/// and text, which is the boxes and always wins. Composing into a grid rather
/// than emitting spans as we go is what lets an edge be drawn without knowing
/// what else has already been drawn where it lands.
pub(super) struct Ink {
    w: usize,
    h: usize,
    bits: Vec<u8>,
    text: Vec<Option<(char, InkStyle)>>,
}

impl Ink {
    pub(super) fn new(w: usize, h: usize) -> Self {
        Self {
            w,
            h,
            bits: vec![0; w * h],
            text: vec![None; w * h],
        }
    }

    /// Bounds-checked index. Everything else goes through this, so a route
    /// that runs off the edge is clipped instead of panicking.
    fn at(&self, x: i32, y: i32) -> Option<usize> {
        if x < 0 || y < 0 || x as usize >= self.w || y as usize >= self.h {
            return None;
        }
        Some(y as usize * self.w + x as usize)
    }

    pub(super) fn mark(&mut self, x: i32, y: i32, dirs: u8) {
        if let Some(i) = self.at(x, y) {
            self.bits[i] |= dirs;
        }
    }

    fn put(&mut self, x: i32, y: i32, ch: char, style: InkStyle) {
        if let Some(i) = self.at(x, y) {
            self.text[i] = Some((ch, style));
        }
    }

    /// A run of horizontal line. Endpoints only get the bit pointing along the
    /// run, so a corner formed with a vertical run turns properly.
    pub(super) fn hline(&mut self, y: i32, x1: i32, x2: i32) {
        let (a, b) = (x1.min(x2), x1.max(x2));
        for x in a..=b {
            let mut dirs = 0;
            if x > a {
                dirs |= LEFT;
            }
            if x < b {
                dirs |= RIGHT;
            }
            self.mark(x, y, dirs);
        }
    }

    pub(super) fn vline(&mut self, x: i32, y1: i32, y2: i32) {
        let (a, b) = (y1.min(y2), y1.max(y2));
        for y in a..=b {
            let mut dirs = 0;
            if y > a {
                dirs |= UP;
            }
            if y < b {
                dirs |= DOWN;
            }
            self.mark(x, y, dirs);
        }
    }

    pub(super) fn draw_box(&mut self, p: &Placed, name: &str, style: InkStyle, g: &Glyphs) {
        let (x0, y0) = (p.col as i32, p.row as i32);
        let x1 = x0 + p.width as i32 - 1;
        let y1 = y0 + Placed::HEIGHT as i32 - 1;
        self.put(x0, y0, g.corners[0], style);
        self.put(x1, y0, g.corners[1], style);
        self.put(x0, y1, g.corners[2], style);
        self.put(x1, y1, g.corners[3], style);
        for x in x0 + 1..x1 {
            self.put(x, y0, g.horizontal, style);
            self.put(x, y1, g.horizontal, style);
        }
        self.put(x0, y0 + 1, g.vertical, style);
        self.put(x1, y0 + 1, g.vertical, style);
        for (i, c) in name.chars().enumerate() {
            self.put(x0 + 1 + i as i32, y0 + 1, c, style);
        }
    }

    /// Write a run of text starting at a cell, clipped at the right edge.
    pub(super) fn write(&mut self, x: i32, y: i32, text: &str, style: InkStyle) {
        for (i, c) in text.chars().enumerate() {
            self.put(x + i as i32, y, c, style);
        }
    }

    /// Turn the grid into one `Line` per row, merging neighboring cells that
    /// share a style so a row is a handful of spans rather than one per column.
    pub(super) fn render(&self, g: &Glyphs, pal: &Palette) -> Vec<Line<'static>> {
        let style_of = |s: InkStyle| match s {
            InkStyle::Selected => pal.text.add_modifier(Modifier::REVERSED),
            // Bold as well as colored: the two directions have to be
            // distinguishable from the files around them on a terminal that
            // renders no color at all, and from each other on one that does.
            InkStyle::Out => pal.map_out.add_modifier(Modifier::BOLD),
            InkStyle::In => pal.map_in.add_modifier(Modifier::BOLD),
            // Everything the cursor does not touch steps back, so the handful
            // of lines that are drawn have the picture to themselves.
            InkStyle::Far => pal.dim,
            InkStyle::Folder => pal.heading,
        };
        let mut out = Vec::with_capacity(self.h);
        for y in 0..self.h {
            let mut spans: Vec<Span> = Vec::new();
            let mut run = String::new();
            let mut run_style: Option<Style> = None;
            for x in 0..self.w {
                let i = y * self.w + x;
                let (ch, style) = match self.text[i] {
                    Some((ch, s)) => (ch, style_of(s)),
                    None if self.bits[i] != 0 => (g.lines[self.bits[i] as usize], pal.text),
                    None => (' ', pal.dim),
                };
                if run_style != Some(style) {
                    if !run.is_empty() {
                        spans.push(Span::styled(
                            std::mem::take(&mut run),
                            run_style.unwrap_or(pal.dim),
                        ));
                    }
                    run_style = Some(style);
                }
                run.push(ch);
            }
            if !run.is_empty() {
                spans.push(Span::styled(run, run_style.unwrap_or(pal.dim)));
            }
            out.push(Line::from(spans));
        }
        out
    }
}

/// Draw the connection between the file under the cursor and one of its
/// neighbors.
///
/// `a` is always the selected file, whichever way the connection runs. A plain
/// line, with nothing on either end: a mutual connection is the same line as a
/// one-way one, and which way it runs is a question the strip underneath
/// answers in words.
///
/// # Why no arrowheads
///
/// A head is one cell, at the far end of a route that has already turned two
/// corners, and at that size the difference between `▸` and `◂` is a smudge —
/// it reads as debris on the end of the line rather than as a direction.
/// Worse, it is debris in a place where two lines from the same trunk arrive a
/// row apart, so the eye reads a column of them as texture. What the direction
/// is actually *for* — which file calls which — is a thing you look up rather
/// than glance at, and the `in:` and `out:` lists below say it in words that
/// cannot be mistaken for a corner glyph.
///
/// Orthogonal on purpose. A character grid has no diagonals worth the name —
/// a diagonal has to be faked out of dots and reads as a smear rather than as
/// a diagram. Right angles are what anyone drawing this on paper would use,
/// and they land on cell boundaries exactly.
///
/// # One trunk, many branches
///
/// Two rules keep this readable, and both were learned by breaking them.
///
/// **A line only travels in a channel.** The grid leaves two clear rows under
/// every box and a clear column beside every slot ([`Channels`]), and a route
/// made of those is visible along its whole length. Aiming straight at the
/// other box and turning at the halfway point — the obvious approach — puts
/// that corner inside some third box, and since boxes are drawn last and win,
/// what you see is a stub leaving one file and an unrelated stub arriving at
/// another with nothing joining them.
///
/// **Every line out of one file shares one trunk.** The vertical always runs
/// down [`Channels::column_by`] of the *selected* file's slot, never the other
/// one's. So a file with ten neighbors draws one spine with ten branches off
/// it, instead of ten separate routes that cross each other on the way. It is
/// the difference between a diagram and a hatch pattern, and it costs nothing:
/// the trunk is a column no box occupies either way.
///
/// The one shape that skips all of this is two neighbors side by side in the
/// same row, which connect straight across the gap between them. Nothing is in
/// the way, and it is the plainest line on the map.
pub(super) fn route(ink: &mut Ink, a: &Placed, b: &Placed, ch: Channels) {
    if a.col == b.col && a.row == b.row {
        return; // the same slot: nothing to draw between them
    }

    // Side to side, for neighbors in the same row.
    if a.row == b.row && a.col.abs_diff(b.col) == ch.slot_w {
        let y = a.middle() as i32;
        let right = b.col > a.col;
        let (near, far) = if right {
            (a.right() as i32, b.col as i32 - 1)
        } else {
            (a.col as i32 - 1, b.right() as i32)
        };
        ink.hline(y, near, far);
        return;
    }

    // Out of the selected file's right edge, down its own trunk, then along a
    // row channel into the other box's top or bottom.
    let ay = a.middle() as i32;
    let cx = ch.column_by(a.col) as i32;
    let below = b.row > a.row;
    // Above, or level with other boxes in between: either way the line arrives
    // underneath.
    let by = if below {
        b.row as i32 - 1
    } else {
        b.bottom() as i32
    };
    let bx = b.col as i32 + 1;

    ink.hline(ay, a.right() as i32, cx);
    ink.vline(cx, ay, by);
    ink.hline(by, cx, bx);
    // One more bit at the far end, turning it from a run that stops a cell
    // short of the border into a junction that visibly touches the box.
    ink.mark(bx, by, if below { DOWN } else { UP });
}

#[cfg(test)]
mod tests {
    use super::*;

    // ---- map routing ------------------------------------------------------

    fn placed(node: usize, col: u16, row: u16, width: u16) -> Placed {
        Placed {
            node,
            col,
            row,
            width,
        }
    }

    /// The geometry `place` would produce for boxes this wide.
    fn channels(slot_w: u16) -> Channels {
        Channels {
            slot_w,
            slot_h: Placed::HEIGHT + 2,
            gutter: slot_w - 3,
        }
    }

    /// Whether a cell is inside a box's borders.
    fn in_box(p: &Placed, x: i32, y: i32) -> bool {
        (p.col as i32..p.col as i32 + p.width as i32).contains(&x)
            && (p.row as i32..p.row as i32 + Placed::HEIGHT as i32).contains(&y)
    }

    /// Assert the drawn route has no dangling end: wherever a line points, it
    /// must reach a line pointing back, an arrowhead, or a box.
    ///
    /// This is the property the whole router exists to satisfy. A route that
    /// stops in empty space is one that went behind a box and came out the far
    /// side, and it is what makes the map look like disconnected stubs.
    fn assert_no_loose_ends(ink: &Ink, boxes: &[&Placed]) {
        let dirs = [
            (UP, 0, -1, DOWN),
            (DOWN, 0, 1, UP),
            (LEFT, -1, 0, RIGHT),
            (RIGHT, 1, 0, LEFT),
        ];
        for y in 0..ink.h as i32 {
            for x in 0..ink.w as i32 {
                let Some(i) = ink.at(x, y) else { continue };
                if ink.bits[i] == 0 {
                    continue;
                }
                for (bit, dx, dy, back) in dirs {
                    if ink.bits[i] & bit == 0 {
                        continue;
                    }
                    let (nx, ny) = (x + dx, y + dy);
                    let Some(n) = ink.at(nx, ny) else { continue };
                    let joined = ink.bits[n] & back != 0
                        || ink.text[n].is_some()
                        || boxes.iter().any(|p| in_box(p, nx, ny));
                    assert!(
                        joined,
                        "the line at ({x},{y}) points at nothing:\n{}",
                        sketch(ink)
                    );
                }
            }
        }
    }

    /// The grid as text, for a failure message.
    fn sketch(ink: &Ink) -> String {
        let g = Glyphs::for_markers(Markers::Arrows);
        (0..ink.h)
            .map(|y| {
                (0..ink.w)
                    .map(|x| match ink.text[y * ink.w + x] {
                        Some((c, _)) => c,
                        None => g.lines[ink.bits[y * ink.w + x] as usize],
                    })
                    .collect::<String>()
            })
            .collect::<Vec<_>>()
            .join("\n")
    }

    /// Every arrangement two boxes can be in, in slot coordinates.
    fn arrangements() -> Vec<(Placed, Placed, &'static str)> {
        let ch = channels(14);
        let slot = |c: u16, r: u16, w: u16| placed(0, c * ch.slot_w, 1 + r * ch.slot_h, w);
        vec![
            (slot(0, 0, 8), slot(1, 0, 9), "neighbors in a row"),
            (slot(0, 0, 8), slot(3, 0, 9), "same row, far apart"),
            (slot(0, 0, 8), slot(0, 1, 11), "directly below"),
            (slot(0, 2, 8), slot(0, 0, 11), "directly above"),
            (slot(1, 0, 8), slot(0, 2, 11), "down and to the left"),
            (slot(0, 0, 8), slot(3, 2, 9), "down and to the right"),
            (slot(3, 2, 9), slot(0, 0, 8), "up and to the left"),
        ]
    }

    #[test]
    fn a_route_never_leaves_a_loose_end() {
        let ch = channels(14);
        for (a, b, what) in arrangements() {
            let mut ink = Ink::new(90, 40);
            route(&mut ink, &a, &b, ch);
            assert_no_loose_ends(&ink, &[&a, &b]);
            assert!(
                ink.bits.iter().any(|b| *b != 0),
                "{what} should have drawn something"
            );
        }
    }

    /// Whether the drawn route visibly meets this box.
    ///
    /// Orientation matters, and it is the whole point of the check. A `─`
    /// sitting immediately right of a border runs *into* it and reads as
    /// attached; the same `─` on the row above a box runs *past* it, parallel,
    /// and reads as a line that stopped nearby for no reason. So a horizontal
    /// end counts on the left and right, and a vertical end above and below.
    fn touches(ink: &Ink, p: &Placed) -> bool {
        let (x0, y0) = (p.col as i32, p.row as i32);
        let (x1, y1) = (x0 + p.width as i32 - 1, y0 + Placed::HEIGHT as i32 - 1);
        let met = |x: i32, y: i32, along: u8| match ink.at(x, y) {
            Some(i) => ink.text[i].is_some() || ink.bits[i] & along != 0,
            None => false,
        };
        let sides = (y0..=y1).any(|y| met(x0 - 1, y, LEFT | RIGHT) || met(x1 + 1, y, LEFT | RIGHT));
        let ends = (x0..=x1).any(|x| met(x, y0 - 1, UP | DOWN) || met(x, y1 + 1, UP | DOWN));
        sides || ends
    }

    #[test]
    fn a_route_meets_both_of_the_boxes_it_joins() {
        // The complement of `a_route_never_leaves_a_loose_end`: that one says
        // the line does not point at nothing, this one says it actually
        // arrives. A run that stops one cell short of a border satisfies the
        // first and fails the second, and with nothing drawn on the end of a
        // line any more, that gap would be all there was to see.
        let ch = channels(14);
        for (a, b, what) in arrangements() {
            let mut ink = Ink::new(90, 40);
            route(&mut ink, &a, &b, ch);
            assert!(
                touches(&ink, &a),
                "{what}: the line never reaches the first box:\n{}",
                sketch(&ink)
            );
            assert!(
                touches(&ink, &b),
                "{what}: the line never reaches the second box:\n{}",
                sketch(&ink)
            );
        }
    }

    #[test]
    fn a_route_never_passes_through_a_box() {
        let ch = channels(14);
        // A third box in the middle of the grid, of the widest kind, standing
        // in for whatever the layout put between the two being joined.
        for (a, b, what) in arrangements() {
            let mut ink = Ink::new(90, 40);
            route(&mut ink, &a, &b, ch);
            for slot_c in 0..5u16 {
                for slot_r in 0..3u16 {
                    let other =
                        placed(9, slot_c * ch.slot_w, 1 + slot_r * ch.slot_h, ch.slot_w - 4);
                    if other.col == a.col && other.row == a.row {
                        continue;
                    }
                    if other.col == b.col && other.row == b.row {
                        continue;
                    }
                    for y in other.row as i32..other.row as i32 + Placed::HEIGHT as i32 {
                        for x in other.col as i32..other.col as i32 + other.width as i32 {
                            let i = ink.at(x, y).expect("inside the grid");
                            assert_eq!(
                                ink.bits[i],
                                0,
                                "{what}: a line crosses the box at slot ({slot_c},{slot_r}) \
                                 — it would vanish behind it:\n{}",
                                sketch(&ink)
                            );
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn a_connection_is_a_plain_line_with_nothing_on_either_end() {
        let ch = channels(14);
        for (a, b, what) in arrangements() {
            let mut ink = Ink::new(90, 40);
            route(&mut ink, &a, &b, ch);
            // `route` puts nothing in the text layer at all — every cell it
            // touches is a line bit, and line bits can only ever render as one
            // of the box-drawing runs or junctions.
            assert!(
                ink.text.iter().all(|t| t.is_none()),
                "{what}: a connection should be line and nothing else:\n{}",
                sketch(&ink)
            );
        }
    }
}

